package com.example

import com.example.ExamQuestionHelper.QSpec

internal object HistoryLiveExamEarlySettlementBank {
  private const val T = "පැරණි ජනාවාස, රාජ්‍ය පාලනය හා ආර්ථිකය"

  private fun q(
    t: String,
    s: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    e: String
  ) = QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun earlySettlementAndAdminQuestions(): List<QSpec> = listOf(
    q(T, "විජය කුමරු ඇතුළු පිරිස ලංකාවට ගොඩබට ස්ථානය වංශකතාවල හැඳින්වෙන්නේ කුමන නමකින්ද?", "තම්බපණ්ණිය", "මහාතිත්ථ", "ගෝකණ්ණ", "ජම්බුකෝලපට්ටන", "විජය කුමරු ඇතුළු පිරිස ගොඩබැසීමේදී දෑත්වල තඹ පැහැති වැලි තැවරුණු බැවින් තම්බපණ්ණි යැයි නම් වූ බව කියැවේ."),
    q(T, "විජය කුමරුගෙන් පසු ලංකාවේ පාලනය භාර ගැනීමට ඉන්දියාවෙන් පැමිණි ඔහුගේ බෑණනුවන් කවුද?", "පණ්ඩුවාසුදේව කුමරු", "පණ්ඩුකාභය කුමරු", "අභය කුමරු", "දීඝගාමිණී කුමරු", "උපතිස්ස ඇමතිගේ තාවකාලික පාලනයෙන් පසු පණ්ඩුවාසුදේව කුමරු රජ විය."),
    q(T, "පණ්ඩුවාසුදේව රජුගේ බිසව වූ භද්දකච්චායනා කුමරියගේ සොහොයුරන් පිහිටුවූ ජනාවාස මොනවාද?", "රාමගෝණ, උරුවෙල, අනුරාධ, විජිත, දීඝායු හා රෝහණ", "සීතාවක හා කෝට්ටේ", "ගම්පොළ හා සෙංකඩගල", "දඹදෙණිය හා යාපහුව", "ශාක්‍ය වංශික කුමාරවරු දිවයිනේ විවිධ ප්‍රදේශවල තම නම්වලින් ජනාවාස පිහිටුවූහ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිම ග්‍රාමීය ජනාවාස බහුලව ව්‍යාප්ත වී තිබූ ප්‍රධාන පාරිසරික කලාපය කුමක්ද?", "වියළි කලාපයේ ගංගා නිම්න ආශ්‍රිත ප්‍රදේශ", "මධ්‍යම කඳුකරයේ අධික ශීතල කඳු මුදුන්", "කඩොලාන වගුරු බිම්", "අතරමැදි වැසි වනාන්තර කඳු වැටි", "මල්වතු ඔය, කලා ඔය, මහවැලි, වලවේ හා කිරිඳි ඔය නිම්න වියළි කලාපීය ගොවි ජනාවාසවලට යෝග්‍ය විය."),
    q(T, "පූර්ව බ්‍රාහ්මී සෙල්ලිපිවල 'ගම' යන ඒකකයට නායකත්වය දුන් පුද්ගලයා හැඳින්වූ නාමය කුමක්ද?", "ගමික", "සෙනපති", "භණ්ඩාගාරික", "රාජගුරු", "ග්‍රාමීය පාලන ඒකකය වූ ගමේ ප්‍රධානියා ගමික ලෙස හැඳින්විණි."),
    q(T, "පැරණි ජනාවාසවල එක් ගමකට හෝ ගම් කිහිපයකට නායකත්වය දුන් ඉහළ ප්‍රභූ පිරිස හැඳින්වූ නාමය කුමක්ද?", "පරුමකවරු", "වඩුවෝ", "දාසයෝ", "නාවිකයෝ", "මහාවංශයේ හා බ්‍රාහ්මී ලිපිවල ප්‍රාදේශීය ප්‍රභූන් පරුමක යන නාමයෙන් දැක්වේ."),
    q(T, "ගමික සහ පරුමකවරුන්ට අමතරව ගෞරවනීය ගෘහපතියන් හැඳින්වීමට සෙල්ලිපිවල භාවිත කළ පදය කුමක්ද?", "ගහපති", "චණ්ඩාල", "පුක්කුස", "වැදි", "ධනවත් ඉඩම් හිමි හා වෙළෙඳ ගෘහපතියන් 'ගහපති' හෙවත් 'ගපති' ලෙස හඳුන්වා ඇත."),
    q(T, "පැරණි සිංහල ජනාවාස ක්‍රමයේදී වැවක් කේන්ද්‍ර කරගෙන ගොඩනැගුණු ගම්මානය හඳුන්වනු ලබන පොදු සංකල්පය කුමක්ද?", "වැවයි - දාගැබයි - ගමයි - පන්සලයි සංකල්පය", "නගරයයි - කොටුවයි - වරායයි", "වතුයායයි - කර්මාන්තශාලාවයි", "කඳවුරයි - බලකොටුවයි", "කුඩා වැව මූලික කරගෙන කුඹුරු, ගොඩගෙවතු, ගම හා විහාරය බිහිවිය."),
    q(T, "පැරණි ලංකාවේ 'ගම් වැව' (Village Tank) මූලික කොට පැවති ජනාවාස ක්‍රමයේදී ගොඩ ඉඩම්වල වගා කළ ක්‍රමය කුමක්ද?", "හේන් ගොවිතැන", "හයිඩ්‍රොපොනික් වගාව", "හරිතාගාර වගාව", "ප්ලාන්ටේෂන් වගාව", "මඩ ඉඩම්වල වී වගාවට අමතරව ගොඩ ඉඩම්වල කුරක්කන්, තල, මුං, මෙනේරි ආදිය හේන් ලෙස වගා කෙරිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ජනාවාස ආශ්‍රිතව 'කසිකර' හෝ 'ගොවි' කර්මාන්තයට අමතරව එක්තරා වෘත්තියක් පදනම් කරගෙන බිහි වූ ගම් හඳුන්වන්නේ කෙසේද?", "වෘත්තීය ගම් (උදා — කුඹල්ගම, කම්මල්ගම, වඩුගම)", "වතුකර ගම්", "සංචාරක ගම්", "නාගරික තට්ටු නිවාස", "එකම ශිල්පය ප්‍රගුණ කළ පිරිස් වෙනම ගම්වල පදිංචිව සිටි බව වංශකතා හා සෙල්ලිපි පෙන්වයි."),
    q(T, "අනුරාධපුර මුල් යුගයේ සිටම මෙරට ප්‍රධාන විදේශ වෙළෙඳ වරාය වූ 'මහාතිත්ථ' වර්තමානයේ හඳුන්වන්නේ කුමන නමකින්ද?", "මාන්තොට (මන්නාරම අසල)", "ත්‍රිකුණාමලය", "හම්බන්තොට", "ගාල්ල", "වයඹදිග වෙරළේ පිහිටි මහාතිත්ථ අනුරාධපුර අගනුවරට ඉතාමත් ආසන්න ප්‍රධාන වරාය විය."),
    q(T, "නැගෙනහිර වෙරළ තීරයේ පිහිටි පැරණි ප්‍රධාන වරායක් වන 'ගෝකණ්ණ' වර්තමානයේ කුමන නගරය ලෙස හඳුනා ගැනේද?", "ත්‍රිකුණාමලය", "මඩකලපුව", "කල්මුණේ", "පොතුවිල්", "මහවැලි ගං මෝය අසල පිහිටි ගෝකණ්ණ තොට පෙරදිග ආසියානු වෙළෙඳාමට ප්‍රකට විය."),
    q(T, "උතුරු වෙරළ තීරයේ පිහිටි, සංඝමිත්තා තෙරණිය ශ්‍රී මහා බෝධි ශාඛාව රැගෙන ගොඩබට පැරණි වරාය කුමක්ද?", "ජම්බුකෝලපට්ටන (දඹකොළ පටුන)", "ඌරාතොට", "ගෝදපවත", "මහාගාම", "යාපනය අර්ධද්වීපයේ පිහිටි ජම්බුකෝලපට්ටන උතුරු ඉන්දියාව හා සම්බන්ධ වූ ප්‍රධාන තොටුපළ විය."),
    q(T, "දකුණු ලංකාවේ වලවේ ගං මෝය ආසන්නයේ පිහිටි, ක්‍රි.ව. 2 වන සියවසේ ගජබාහු රජුගේ සෙල්ලිපියක් හමු වූ පැරණි වරාය කුමක්ද?", "ගෝදපවත (ගොඩවාය)", "මාන්තොට", "සලාවත", "පල්ලවවංක", "ගොඩවාය විහාරයට වරාය තීරු බදු පූජා කළ බව දැක්වෙන ලිපිය එහි වෙළෙඳ වැදගත්කම පෙන්වයි."),
    q(T, "අම්බලන්තොට ගොඩවාය සෙල්ලිපියෙන් හෙළි වන වැදගත් රාජ්‍ය ආර්ථික කරුණ කුමක්ද?", "වරායෙන් අය කළ තීරු බදු (සුංකම්) විහාර නඩත්තුවට පැවරීම", "පෘතුගීසීන්ට වරාය බදු දීම", "ධීවර කර්මාන්තය තහනම් කිරීම", "වරාය වසා දැමීම", "වෙළෙඳ වරායවලින් රජයට තීරු බදු ආදායමක් ලැබුණු බව මෙම ලිපියෙන් තහවුරු වේ."),
    q(T, "මන්නාරම් බොක්ක හා දිවයිනේ මැණික් පතල් නිසා පැරණි ලංකාවෙන් විදේශයන්ට අපනයනය කළ ප්‍රධාන සුඛෝපභෝගී භාණ්ඩ මොනවාද?", "මුතු, මැණික්, ඇත්දළ හා කැස්බෑ කටු", "තේ, රබර් හා පොල්", "ගල් අඟුරු හා ඛනිජ තෙල්", "මෝටර් රථ කොටස්", "ග්‍රීක, රෝම හා චීන වාර්තාවල ලංකාවේ මුතු හා මැණික් ගැන ඉහළින් වර්ණනා කර ඇත."),
    q(T, "පැරණි රාජ්‍ය පාලන ක්‍රමය තුළ රජතුමා හැඳින්වීමට භාවිත කළ 'ගාමිණී' යන ගෞරව නාමයේ මූලික අර්ථය කුමක්ද?", "ග්‍රාමීය ප්‍රජාවේ නායකයා හෝ සමූහයේ ප්‍රධානියා", "විදේශීය අධිරාජ්‍යයා", "වෙළෙඳ සංගම් ලේකම්", "ආරෝග්‍යශාලා වෛද්‍යවරයා", "දුටුගැමුණු, සද්ධාතිස්ස, වළගම්බා ආදී රජවරු තම නම් සමඟ 'ගාමිණී' පදවිය භාවිත කළහ."),
    q(T, "පැරණි ලංකාවේ රාජ්‍ය පාලකයා අනුගමනය කළ යුතු යහපත් ප්‍රතිපත්ති පද්ධතිය ලෙස බෞද්ධ සමාජය පිළිගත් ඉගැන්වීම කුමක්ද?", "දස රාජ ධර්මය", "පංචශීලය පමණක්", "චතුරාර්ය සත්‍යය පමණක්", "කෝල්බෲක් ප්‍රතිසංස්කරණ", "දානය, ශීලය, පරිත්‍යාගය, ඍජු බව ආදී දස රාජ ධර්ම අනුව රජු පාලනය ගෙන යා යුතු විය."),
    q(T, "අනුරාධපුර යුගයේ රජවරුන් විසින් භාවිත කළ 'දේවානම්පිය' යන විරුද නාමයේ අර්ථය කුමක්ද?", "දෙවියන්ට ප්‍රිය වූ තැනැත්තා", "යුද්ධයට දක්ෂ තැනැත්තා", "මුහුදු සෙන්පති", "ධනවත් වෙළෙන්දා", "ඉන්දියාවේ අශෝක අධිරාජ්‍යයා මෙන් තිස්ස රජු ඇතුළු මුල් ලාංකික රජවරු මෙම විරුදය භාවිත කළහ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ රාජ්‍ය උරුමය හිමිවීමේදී පියාගෙන් පුතුට පමණක් නොව වැඩිමහල් සොහොයුරාගෙන් බාල සොහොයුරාටද උරුම වීමේ ක්‍රමය කෙසේ වීද?", "සොහොයුරන් අතර පිළිවෙළින් රජකම මාරු වී අවසානයේ වැඩිමහල් සොහොයුරාගේ පුතුට යාම", "රජුගේ බිරිඳගේ සොහොයුරාට පමණක් යාම", "ජනමත විචාරණයකින් තෝරා ගැනීම", "සෙනෙවියන් අතර ලොතරැයි ඇදීම", "සද්ධාතිස්ස, දුටුගැමුණු ආදී අවස්ථාවලදී සහ පසුකාලීන අනුරාධපුර යුගයේ මෙම ක්‍රමය බහුලව ක්‍රියාත්මක විය."),
    q(T, "රජුට රාජ්‍ය පාලන කටයුතුවලදී උපදෙස් දීමට සිටි ප්‍රධාන නිලධාරි මණ්ඩලය හඳුන්වන්නේ කුමන නමකින්ද?", "අමාත්‍ය මණ්ඩලය (අමති / ඇමතිවරු)", "පාර්ලිමේන්තුව", "රාජ්‍ය මන්ත්‍රණ සභාව", "ව්‍යවස්ථාදායක සභාව", "මහා අමාත්‍ය, සෙනෙවි, භාණ්ඩාගාරික, පුරෝහිත ආදී ඇමතිවරු රජුට සහාය වූහ."),
    q(T, "පැරණි ලංකාවේ හමුදා සංවිධානයේ ප්‍රධානියා හඳුන්වනු ලැබූ තනතුරු නාමය කුමක්ද?", "සේනාපති (සෙනෙවි)", "මහාලේඛක", "ගණකාධිකාරි", "අධිකරණ නායක", "රාජ්‍ය ආරක්ෂාව හා යුද මෙහෙයුම් භාර ඉහළම හමුදා නිලධාරියා සේනාපති නම් විය."),
    q(T, "සාම්ප්‍රදායික ඉන්දියානු හා ශ්‍රී ලාංකික යුද සම්ප්‍රදායේ 'චතුරංගනී සේනාව' යන්නට අයත් අංග හතර මොනවාද?", "ඇත්, අස්, රිය සහ පාබල", "නැව්, ගුවන්, කාලතුවක්කු හා පාබල", "දුනු, කඩු, හෙල්ල හා පලිහ", "තුවක්කු, බෝම්බ, අශ්ව හා පාබල", "පුරාණ රාජකීය හමුදා හස්ති, අශ්ව, රථ හා පාබල යන අංග හතරෙන් සමන්විත විය."),
    q(T, "පැරණි ලංකාවේ ප්‍රාදේශීය පාලන කටයුතුවලදී දක්නට ලැබුණු ප්‍රධාන භූගෝලීය බෙදීම් තුන මොනවාද?", "රජරට (පිහිටි රට), මායා රට සහ රුහුණු රට", "උතුරු, මධ්‍යම හා දකුණු පළාත්", "බස්නාහිර, සබරගමුව හා ඌව", "කන්ද උඩරට, කෝට්ටේ හා සීතාවක", "ඓතිහාසික වශයෙන් දිවයින ත්‍රිසිංහලය ලෙස රජරට, මායා හා රුහුණු වශයෙන් බෙදී පැවතුණි."),
    q(T, "පැරණි වාරි කර්මාන්ත හා ඉඩම්වලින් ජලය ලබා ගැනීම වෙනුවෙන් රජයට ගෙවූ ජල බද්ද හැඳින්වූ නාමය කුමක්ද?", "දකපති (උදකභාග)", "බෝජකපති", "මරාල බද්ද", "ඇඟ බද්ද", "වැව් හා ඇළ මාර්ගවලින් කුඹුරුවලට ජලය ගැනීම වෙනුවෙන් අය කළ බද්ද දකපති නම් විය."),
    q(T, "කුඹුරු හෝ ඉඩම් භුක්ති විඳීම වෙනුවෙන් ඉඩම් අයිතිකරුට හෝ රජයට ගෙවූ ඉඩම් බද්ද හැඳින්වූ නාමය කුමක්ද?", "බෝජකපති", "දකපති", "විශේෂ තීරු බදු", "වැට් බද්ද", "ඉඩමේ අස්වැන්නෙන් කොටසක් රජුට හෝ ප්‍රදානලාභියාට ගෙවීම බෝජකපති ලෙස සෙල්ලිපිවල දැක්වේ."),
    q(T, "පැරණි වෙළෙඳුන් සංවිධානය වී සිටි වෙළෙඳ සංගම් හෙවත් ශ්‍රේණි සෙල්ලිපිවල හඳුන්වා ඇත්තේ කුමන නමකින්ද?", "පූග (හෝ නියම / සේනි)", "සමිතිය", "මණ්ඩලය", "සමාගම", "අභයගිරි හා බදුල්ල ආදී සෙල්ලිපිවල 'පූග' හා 'නියම' නමින් වෙළෙඳ හා කර්මාන්ත ශ්‍රේණි දැක්වේ."),
    q(T, "පැරණි සමාජයේ වෛද්‍ය සේවය ක්‍රමවත්ව පැවති බවට සාක්ෂි දරන අනුරාධපුර හා මිහින්තලේ රෝහල් සංකීර්ණවල විශේෂ ලක්ෂණය කුමක්ද?", "ශල්‍ය උපකරණ, බෙහෙත් ඔරු සහ රෝගීන් නේවාසිකව තබන කුටි සැලසුම", "එක්ස්-රේ කාමර", "සිමෙන්ති ඇඳන්", "යකඩ වහල", "මිහින්තලේ රෝහලේ ඖෂධ තෙල් ගිල්වන ගල් බෙහෙත් ඔරුව සහ වෛද්‍ය උපකරණ අදටත් දැකිය හැකිය."),
    q(T, "ගැබිනි මව්වරුන් සහ අන්ධ, රෝගී පුද්ගලයන් සඳහා ආරෝග්‍යශාලා හා ඖෂධශාලා පිහිටුවූ කීර්තිමත් අනුරාධපුර රජු කවුද?", "බුද්ධදාස රජු", "කාශ්‍යප රජු", "එළාර රජු", "විජය රජු", "වෛද්‍ය ශාස්ත්‍රයේ කෙළ පැමිණි බුද්ධදාස රජු සෑම ගම් දහයකටම වෛද්‍යවරයෙකු පත් කර 'සාරාර්ථ සංග්‍රහය' රචනා කළේය."),
    q(T, "පැරණි ලංකාවේ වැව් ජලය මුදා හැරීම පාලනය කිරීමට නිර්මාණය කළ විශිෂ්ට තාක්ෂණික උපාංගය කුමක්ද?", "බිසෝකොටුව (වැව් සොරොව්ව)", "ජල මෝටරය", "සුළං පෙත්ත", "කොන්ක්‍රීට් පාලම", "වැව් බැම්මට හානි නොවී අධික ජල පීඩනය පාලනය කරමින් ජලය පිට කිරීමට බිසෝකොටුව නිපදවිණි."),
    q(T, "වැව් බැම්ම පිටාර ගැලීමෙන් කැඩී යාම වැළැක්වීම සඳහා අතිරික්ත ජලය පිට කිරීමට ඉදිකළ කොටස කුමක්ද?", "පිටවාන (Spillway)", "බිසෝකොටුව", "රළපනාව", "සොරොව්ව", "මහ වැසි සමයේ වැව පිරුණු විට ආරක්ෂිතව අතිරික්ත ජලය පිට කිරීමට පිටවාන ඉදි කෙරේ."),
    q(T, "සුළඟ නිසා ඇතිවන රළ පහරින් වැව් බැම්ම ඛාදනය වීම වැළැක්වීමට වැව් බැම්මේ ඇතුළු බෑවුමේ අතුරන ලද ගල් ආවරණය කුමක්ද?", "රළපනාව", "පිටවාන", "ඇළ බැම්ම", "සොරොව් කට", "කළුගල් ඇතිරූ රළපනාව වැව් බැම්ම රළ පහරින් ආරක්ෂා කරයි."),
    q(T, "එක් ප්‍රධාන ගඟක් හරස් කර වේල්ලක් (අමුණක්) බැඳ ඇළ මාර්ග ඔස්සේ වැව් ගණනාවකට ජලය සැපයීමේ ක්‍රමය හඳුන්වන්නේ කෙසේද?", "අමුණු හා ඇළ මාර්ග පද්ධතිය (උදා — ඇළහැර අමුණ හා යෝධ ඇළ)", "විදුලි බලාගාර ක්‍රමය", "භූගත නළ පද්ධතිය", "කෘත්‍රිම වැසි ක්‍රමය", "මහා වාරි කර්මාන්තවලදී අමුණු මගින් ගංගා ජලය හරවා ඇළ මාර්ගවලින් වැව් පුරවන ලදී."),
    q(T, "ගමක කුඩා වැව් කිහිපයක් ඉහළ සිට පහළට එකිනෙකට සම්බන්ධ කරමින් ජලය අරපිරිමැස්මෙන් භාවිත කළ සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "එල්ලංගා පද්ධතිය (Cascade System)", "ජලවිදුලි පද්ධතිය", "නළ ළිං පද්ධතිය", "මුහුදු ජල පවිත්‍රාගාරය", "එක් වැවකින් ඉතිරි වන ජලය ඊළඟ පහළ වැවට ගලා යන එල්ලංගා ක්‍රමය වියළි කලාපයේ විශිෂ්ට පාරිසරික නිර්මාණයකි."),
    q(T, "පැරණි සමාජයේ වැව් බැමි සහ වාරි ඇළ මාර්ග නඩත්තු කිරීම සඳහා ප්‍රජාව සාමූහිකව සේවය ලබා දුන් ක්‍රමය කුමක්ද?", "රාජකාරි ක්‍රමය / පංගු ක්‍රමය", "කම්කරු වෘත්තීය සමිති", "විදේශීය කොන්ත්‍රාත්", "මුදල් ගෙවා ගත් කුලී හේවායන්", "ගමේ ගොවීන් තම කුඹුරු ප්‍රමාණය අනුව වැව් කණ්ඩියේ පංගු ශුද්ධ කර අලුත්වැඩියා කළහ."),
    q(T, "පැරණි ලංකාවේ අධිකරණ කටයුතු හා නීති පරිපාලනය සම්බන්ධයෙන් පැවති විශේෂ ලක්ෂණයක් වන්නේ කුමක්ද?", "රජු ඉහළම අධිකරණ බලධාරියා වූ අතර ග්‍රාමීය මට්ටමින් දසගම් හා සභාවල නඩු විසඳීම", "විදේශීය විනිසුරන් පමණක් නඩු ඇසීම", "අධිකරණ කිසිවක් නොතිබීම", "සෑම වරදකටම පිටුවහල් කිරීම", "රාජසභාවේ සිට ග්‍රාමීය පාලන ඒකක දක්වා නීතිය ක්‍රියාත්මක වූ බව වේවැල්කැටිය ලිපියෙන් පෙනේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ කෘෂිකර්මාන්තයේදී කුඹුරු ගොවිතැන සඳහා ජලය සැපයූ භූමි කලාපවලට අමතරව අලුතින් වැවක් තනා එහි ජලයෙන් අස්වැද්දූ කුඹුරු බද්දෙන් නිදහස් කළේ ඇයි?", "නව ඉඩම් අස්වැද්දීම හා ආහාර නිෂ්පාදනය දිරිමත් කිරීමට", "ජනයා නගරයෙන් පලවා හැරීමට", "රජුට බදු අවශ්‍ය නොවූ නිසා", "වැව් වියළී යාමට", "වසභ වැනි රජවරු කෘෂිකර්මය නැංවීමට පෞද්ගලික වැව් තැනීමට දිරි දුන්හ."),
    q(T, "පැරණි ලංකාවේ අයබදු අය කිරීමේදී මුදලින් මෙන්ම ධාන්‍ය හා ශ්‍රමයෙන්ද බදු ගෙවීමට හැකි වූයේ ඇයි?", "ස්වයංපෝෂිත කෘෂිකාර්මික ආර්ථිකයක් පැවති බැවින්", "කාසි කිසිසේත්ම නොතිබූ බැවින්", "බැංකු පද්ධතිය සම්පූර්ණයෙන් බිඳ වැටී තිබූ බැවින්", "ලන්දේසි නීතිය නිසා", "භාණ්ඩ හුවමාරුව හා ගොවි ශ්‍රම දායකත්වය සමාජයේ සුලභව පැවතුණි."),
    q(T, "පැරණි ලංකාවේ යකඩ, තඹ හා පිත්තල භාණ්ඩ නිපදවූ කර්මාන්තකරුවන් හඳුන්වනු ලැබූයේ කුමන නාමයන්ගෙන්ද?", "කම්මල්කරුවන් හා ලෝකුරුවන් (තඹකාර)", "වඩුවන්", "සිත්තරුන්", "සන්නාලියන්", "පැරණි සෙල්ලිපිවල 'කබර' (යකඩ වැඩ කරන්නා) හා 'තඹකාර' ආදී ශිල්පීන් ගැන සඳහන් වේ."),
    q(T, "අනුරාධපුර යුගයේ මැණික් කර්මාන්තය හා සම්බන්ධව විදේශීය වෙළෙඳපොළේ ඉහළ ඉල්ලුමක් පැවති ප්‍රධාන මැණික් වර්ග මොනවාද?", "නිල් මැණික් (Sapphire) සහ රතු මැණික් (Ruby)", "ගල් අඟුරු", "තිරුවාණ ගල් පමණක්", "හුණුගල්", "රත්නද්වීප යන විරුදාවලිය ලැබීමට තරම් උසස් නිල් හා රතු මැණික් ලංකාවෙන් අපනයනය කෙරිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ කාන්තාවන්ට සමාජයේ හිමිව තිබූ තත්ත්වය පිළිබඳව පූර්ව බ්‍රාහ්මී ලෙන් ලිපිවලින් හෙළි වන්නේ කුමක්ද?", "දේපළ හිමිකම සහ ස්වාධීනව ලෙන් පූජා කිරීමේ අයිතිය තිබූ බව", "නිවසින් පිටතට යාම තහනම් වූ බව", "ලිපිවල කිසිදු කාන්තා නමක් නොමැති බව", "අධ්‍යාපනය තහනම් වූ බව", "උපාසිකාවන්, රැජිනියන් හා පරුමක දියණියන් ස්වාධීනව සංඝයාට ලෙන් පිදූ බව ලිපිවල දැක්වේ."),
    q(T, "පැරණි ලංකාවේ රාජ්‍ය පාලනය කළ ප්‍රථම කාන්තා පාලිකාව ලෙස වංශකතාවල සඳහන් වන්නේ කවුද?", "අනුලා දේවිය", "ලීලාවතී රැජින", "කල්‍යාණවතී රැජින", "සුගලා දේවිය", "ක්‍රි.පූ. 1 වන සියවසේ අනුලා දේවිය දකුණු ආසියාවේ පළමු රාජ්‍ය පාලිකාවන්ගෙන් කෙනෙකි."),
    q(T, "වෙළෙඳාමේදී දුර බැහැර රටවල සිට ලංකාවට පැමිණි විදේශීය වෙළෙඳුන් අනුරාධපුරයේ පදිංචිව සිටි බවට සාධකයක් වන්නේ කුමක්ද?", "පණ්ඩුකාභය රජු යෝනයන් (ග්‍රීක/පර්සියානු වෙළෙඳුන්) සඳහා වෙනම ප්‍රදේශයක් වෙන් කිරීම", "අනුරාධපුරයේ පෘතුගීසි කොටුව තැනීම", "කොළඹ වරාය විවෘත කිරීම", "මහනුවර ඉංග්‍රීසි පල්ලිය සෑදීම", "මහාවංශයේ යෝන නම් විදේශීය වෙළෙඳුන් සඳහා අනුරාධපුරයේ වෙනම පෙදෙසක් වෙන් කළ බව කියැවේ."),
    q(T, "පැරණි ලංකාවේ ප්‍රධාන වශයෙන් අභ්‍යන්තර ප්‍රවාහනය සඳහා භාවිත කළ මාධ්‍ය මොනවාද?", "ගොන් කරත්ත, පාරු සහ තවලම් ක්‍රමය", "දුම්රිය සහ මෝටර් රථ", "ට්‍රෑම් රථ", "බයිසිකල්", "ගංගා ඔස්සේ පාරුවලින්ද ගොඩබිම් මංමාවත්වල කරත්ත හා තවලම් මගින්ද භාණ්ඩ ප්‍රවාහනය විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ඉඩම් අයිතිය සම්බන්ධයෙන් පැවති ප්‍රධාන මූලධර්මය කුමක්ද?", "රටේ සියලු ඉඩම්වල පරම අයිතිකරු රජු වුවද පෞද්ගලික භුක්තිය හා පැවරීම පිළිගත් බව", "කිසිවෙකුට ඉඩම් වගා කිරීමට නොහැකි වූ බව", "විදේශිකයන්ට පමණක් ඉඩම් අයිති වූ බව", "විහාරස්ථානවලට ඉඩම් තහනම් වූ බව", "'වතහිමි' හෙවත් භූපති ලෙස රජු සැලකුණද ගොවීන්ට ඉඩම් පරම්පරාවෙන් භුක්ති විඳීමේ අයිතිය තිබුණි."),
    q(T, "පැරණි ලංකාවේ පැවති 'පමුණු' හෙවත් 'පරවේණි' ඉඩම් ක්‍රමයේ විශේෂත්වය කුමක්ද?", "පරම්පරාවෙන් පරම්පරාවට අඛණ්ඩව උරුම වන ස්ථිර ඉඩම් අයිතියක් වීම", "වසරකට පසු රජයට පවරා ගන්නා ඉඩම් වීම", "කෘෂිකර්මයට නුසුදුසු ඉඩම් වීම", "මුහුදු බඩ වරාය ඉඩම් පමණක් වීම", "රාජ්‍ය සේවය හෝ විශේෂ ගෞරවය වෙනුවෙන් පරම්පරාගතව ලැබුණු ඉඩම් පමුණු/පරවේණි නම් විය."),
    q(T, "දිවෙල් ඉඩම් (Maintenance Lands) ලෙස පැරණි රාජ්‍ය පාලන ක්‍රමයේදී හැඳින්වූයේ මොනවාද?", "රාජ්‍ය නිලධාරීන්ගේ සේවය වෙනුවෙන් වැටුප් ලෙස භුක්ති විඳීමට ලබා දුන් ඉඩම්", "මුහුදින් ගොඩ කළ ඉඩම්", "භික්ෂූන් වහන්සේලාට පූජා කළ උයන්", "පාළු වනාන්තර ඉඩම්", "නිලතල දැරූ අයට එම තනතුර දරන තාක් ආදායම් ලබා ගැනීමට දිවෙල් ඉඩම් පැවරිණි."),
    q(T, "විහාරස්ථාන හා සංඝයා වහන්සේලාගේ නඩත්තුව සඳහා රජවරුන් හා ප්‍රභූන් විසින් පූජා කළ ඉඩම් හැඳින්වූ නාමය කුමක්ද?", "විහාරගම් (සඟසතු ඉඩම්)", "නින්දගම්", "ගබඩාගම්", "මුඩුබිම්", "විහාරාරාමවල නඩත්තුවට හා දානමාන කටයුතුවලට වෙන් කළ ගම් විහාරගම් ලෙස හැඳින්විණි."),
    q(T, "රජුගේ පෞද්ගලික ප්‍රයෝජනය හා මාලිගයේ ආහාර අවශ්‍යතා සපුරා ගැනීම සඳහා වෙන් කර තිබූ ඉඩම් හඳුන්වන්නේ කුමන නමින්ද?", "ගබඩාගම්", "දේවාලගම්", "විහාරගම්", "පන්ගු ඉඩම්", "රජුගේ ගබඩාවට ධාන්‍ය හා සම්පත් සැපයූ ගම් ගබඩාගම් ලෙස හඳුන්වනු ලැබීය."),
    q(T, "පැරණි ලංකාවේ 'ආරෝග්‍යශාලා' මෙන්ම වන්දනාකරුවන් හා අසරණයන් සඳහා ආහාර සැපයූ ආයතන හඳුන්වන්නේ කුමන නමකින්ද?", "දාන ශාලා (මහාපාලි දාන ශාලාව වැනි)", "බැංකු ශාලා", "වෙළෙඳ මධ්‍යස්ථාන", "තානායම් පමණක්", "අනුරාධපුර ඇතුළුනුවර ඇති මහාපාලි දාන ශාලාව දහස් ගණනකට දිනපතා බත් බෙදූ ස්ථානයකි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'අශ්ව වෙළෙඳාම' හා සම්බන්ධව අපට සමීප සබඳතා පැවති විදේශීය ප්‍රදේශ මොනවාද?", "සින්ධු ප්‍රදේශය (වයඹදිග ඉන්දියාව), පර්සියාව හා අරාබිය", "දකුණු ඇමරිකාව", "ඕස්ට්‍රේලියාව", "ඇන්ටාක්ටිකාව", "රාජකීය හමුදාව හා ප්‍රවාහනය සඳහා උසස් වර්ගයේ අශ්වයන් මන්නාරම හරහා ආනයනය කෙරිණි."),
    q(T, "විදේශීය වෙළෙඳුන් ලංකාවෙන් ප්‍රධාන වශයෙන් 'කුරුඳු' වෙනුවට අනුරාධපුර යුගයේදී ඉතා ඉහළින් මිලදී ගත්තේ මොනවාද?", "මුතු, මැණික්, ඇත්දළ හා රෙදිපිළි", "රබර් හා පොල්", "තේ සහ කොකෝවා", "සිමෙන්ති සහ යකඩ", "කුරුඳු අපනයනය ප්‍රධාන වශයෙන් පසුකාලීන (දඹදෙණි-කෝට්ටේ) යුගවල වර්ධනය වූ අතර මුල් යුගයේ මුතු-මැණික් ප්‍රමුඛ විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ධාන්‍ය මැනීම සඳහා භාවිත කළ සාම්ප්‍රදායික මිනුම් ඒකක මොනවාද?", "අමුණ, පෑල, කුරුණිය සහ ලාසය", "කිලෝග්‍රෑම් සහ ටොන්", "ලීටර් සහ මිලිලීටර්", "මීටර් සහ හෙක්ටයාර්", "වී හා ඉඩම් ප්‍රමාණ මැනීමට අමුණු, පෑල හා කුරුණි යන දේශීය මිනුම් ක්‍රම භාවිත විය."),
    q(T, "පුරාණ සිංහල සමාජයේ දිග මැනීම සඳහා භාවිත කළ සාම්ප්‍රදායික මිනුම් ඒකකයක් වන්නේ කුමක්ද?", "රියන, වියත, බඹය සහ ගව්ව", "සැතපුම හා කිලෝමීටරය", "සෙන්ටිමීටරය", "යාරය හා අඟල", "ගොඩනැගිලි හා දුර ප්‍රමාණ මැනීමට ඇඟිලි, වියත්, රියන් හා යොදුන් භාවිත කෙරිණි."),
    q(T, "කාලය මැනීම සඳහා පැරණි ශ්‍රී ලංකාවේ භාවිත කළ සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "පැය තැටිය (ජල ඔරලෝසුව) සහ පැය ගණනය", "ඩිජිටල් ඔරලෝසුව", "පරමාණුක ඔරලෝසුව", "සූර්ය පැනල", "ජල බඳුනක පාවෙන සිදුරු සහිත කෝප්පයක් ගිලීමට ගතවන කාලය අනුව පැය ගණනය කෙරිණි."),
    q(T, "පැරණි ලංකාවේ ශිෂ්‍යයන්ට අකුරු, ධර්මය හා ශාස්ත්‍ර ඉගැන්වීමේ ප්‍රධාන මධ්‍යස්ථාන ලෙස ක්‍රියා කළේ මොනවාද?", "ගමේ පන්සල සහ ප්‍රධාන පිරිවෙන්", "රජයේ ඉංග්‍රීසි පාසල්", "වෙළෙඳසැල්", "නාවික කඳවුරු", "භික්ෂූන් වහන්සේලාගේ මූලිකත්වයෙන් පන්සල් හා මහාවිහාරය, අභයගිරිය වැනි පිරිවෙන්වල අධ්‍යාපනය ලැබිණි."),
    q(T, "විදේශීය ශිෂ්‍යයන් හා භික්ෂූන් පවා අධ්‍යාපනය ලැබීමට පැමිණි අනුරාධපුර යුගයේ ජාත්‍යන්තර විද්‍යාස්ථාන මොනවාද?", "මහාවිහාරය, අභයගිරි විහාරය සහ ජේතවනාරාමය", "විද්‍යෝදය හා විද්‍යාලංකාර පිරිවෙන්", "කෝට්ටේ සුනේත්‍රාදේවි පිරිවෙන", "ලංකා විශ්වවිද්‍යාලය", "ඉන්දියාව, චීනය, ජාවා හා තායිලන්තය වැනි රටවලින් පවා භික්ෂූන් අනුරාධපුරයට පැමිණියහ."),
    q(T, "අනුරාධපුර යුගයේ සිටම පැවති 'වන සංරක්ෂණ' හා 'සතුන් ආරක්ෂා කිරීමේ' රාජ්‍ය ප්‍රතිපත්තියට නිදසුනක් වන්නේ කුමක්ද?", "අමාඝාත ආඥා පනවා සතුන් මැරීම තහනම් කිරීම", "සියලු වනාන්තර කපා හෙළීම", "දඩයම රජයේ රැකියාවක් කිරීම", "ඇතුන් අපනයනය කිරීම පමණක්", "නිශ්ශංකමල්ල හා අනුරාධපුර රජවරු වැව් හා විහාර අසල 'අභය භූමි' ප්‍රකාශයට පත් කළහ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණි කෘෂිකාර්මික සමාජය තුළ 'ගොවි බිම්වල අස්වැන්න නෙළීමේදී' පවුල් එකිනෙකාට උදව් කර ගත් සාමූහික ක්‍රමය කුමක්ද?", "අත්තම (අත්තම් ක්‍රමය)", "කොටස් වෙළෙඳපොළ", "වැටුප් කම්කරු ක්‍රමය", "යන්ත්‍ර කුලියට ගැනීම", "ශ්‍රම හුවමාරුව මත පදනම් වූ අත්තම් ක්‍රමය ග්‍රාමීය සමගිය හා ආර්ථික සහයෝගීතාව වර්ධනය කළේය."),
    q(T, "පැරණි රාජ්‍ය පාලන ක්‍රමයේදී 'පුරෝහිත' තනතුර දැරූ නිලධාරියාගේ ප්‍රධාන කාර්යභාරය කුමක් වීද?", "රාජ්‍ය චාරිත්‍ර, නක්ෂත්‍ර කටයුතු හා ආගමික උපදෙස් ලබා දීම", "වැව් බැඳීම", "වෙළෙඳ බදු එකතු කිරීම", "අශ්වයන් පුහුණු කිරීම", "මුල් යුගයේ බ්‍රාහ්මණ පුරෝහිතවරු රාජාභිෂේක හා රාජසභා චාරිත්‍ර මෙහෙයවූහ."),
    q(T, "රාජ්‍ය ලේඛන, ආඥා හා ප්‍රදාන සටහන් කිරීම භාරව සිටි ප්‍රධාන ලේකම්වරයා හඳුන්වනු ලැබූ පැරණි තනතුරු නාමය කුමක්ද?", "මහලේ / මහාලේඛක", "සේනාපති", "භාණ්ඩාගාරික", "දොරටුපාල", "රාජසභාවේ ලිපි ලේඛන කටයුතු සංවිධානය කිරීම මහලේ තනතුරට පැවරී තිබුණි."),
    q(T, "රාජ්‍යයේ මුදල්, රන් රිදී හා වටිනා වස්තුව භාරව කටයුතු කළ ප්‍රධාන නිලධාරියා පූර්ව බ්‍රාහ්මී සෙල්ලිපිවල හඳුන්වා ඇත්තේ කුමන නමකින්ද?", "භඩකරික (භාණ්ඩාගාරික)", "අඩෙක", "බත", "පරුමක", "රාජ්‍ය භාණ්ඩාගාරය භාරව සිටි නිලධාරීන් බ්‍රාහ්මී ලිපිවල 'භඩකරික' ලෙස සඳහන් වේ."),
    q(T, "පැරණි ලංකාවේ අශ්ව හා ඇත් සේනා භාර ප්‍රධාන නිලධාරීන් බ්‍රාහ්මී සෙල්ලිපිවල හැඳින්වෙන්නේ කුමන නම්වලින්ද?", "අස අඩෙක (අශ්ව අධ්‍යක්ෂ) හා හති අඩෙක (හස්ති අධ්‍යක්ෂ)", "නාවික අඩෙක", "රූප අඩෙක", "වෙළෙඳ අඩෙක", "අශ්ව හා ඇත් පන්ති පරිපාලනය සඳහා විශේෂිත 'අඩෙක' (අධ්‍යක්ෂ) නිලධාරීන් පත් කර තිබුණි."),
    q(T, "පැරණි ජනාවාසවල වැව්වල නඩත්තුව හා ජල බෙදා හැරීම භාරව සිටි ප්‍රාදේශීය නිලධාරියා හඳුන්වන්නේ කුමන නමකින්ද?", "වැවි අඩෙක / වෙල් විදානේ (පසුකාලීනව)", "මුදලි", "රටේ මහත්තයා", "අදිකාරම්", "වැව් ජලය සාධාරණව බෙදා හැරීම හා බැමි ආරක්ෂා කිරීම වැව් පරිපාලන නිලධාරීන්ගේ වගකීම විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'මහාසම්මත' සංකල්පය මගින් ප්‍රකාශ වන දේශපාලන අදහස කුමක්ද?", "මහජනතාවගේ එකඟතාව හා කැමැත්ත මත සාමය රැකීමට රජෙකු පත් වූ බව", "රජු දෙවියන් විසින් පමණක් පත් කළ බව", "හමුදා බලයෙන් පමණක් පාලනය කළ බව", "විදේශිකයන් පාලකයා තේරූ බව", "බෞද්ධ සමාජ චින්තනයට අනුව රජු ජනතා සුබසෙත සඳහා පොදු සම්මුතියෙන් පත් වූ පාලකයෙකි."),
    q(T, "අනුරාධපුර යුගයේ රජවරුන් රාජ්‍යත්වය තහවුරු කර ගැනීමට බෞද්ධ ශාසනය සමඟ පැවැත්වූ සමීප සබඳතාව පෙන්වන ප්‍රධාන සංකේත මොනවාද?", "ශ්‍රී මහා බෝධිය, ශ්‍රී දළදා වහන්සේ සහ මහා ස්තූප ආරක්ෂා කිරීම", "විදේශීය කොඩි එසවීම", "බලකොටු කඩා දැමීම", "සංඝයාට බදු පැනවීම", "දළදා වහන්සේගේ හා බුදු සසුනේ ආරක්ෂකයා වීම රජෙකුට ජනතා ප්‍රසාදය දිනා ගැනීමට අත්‍යවශ්‍ය විය."),
    q(T, "පැරණි ග්‍රාමීය පාලනයේදී ගම් කිහිපයක ප්‍රධානීන් එක්ව ක්‍රියාත්මක කළ 'දසගම්' ක්‍රමයේ මූලික කාර්යය කුමක් වීද?", "ගම් දහයක සාමය රැකීම, සොර සතුරු උවදුරු මැඩීම හා සුළු ආරවුල් විසඳීම", "විදේශ වෙළෙඳ ගිවිසුම් අත්සන් කිරීම", "රාජකීය මාලිගා තැනීම", "කාසි අච්චු ගැසීම", "වේවැල්කැටිය ලිපිය අනුව ගමේ නීතිය හා සාමය දසගම් ඇත්තන් මගින් පාලනය විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'මහා ග්‍රාම' හා 'නිගම' යන නම්වලින් හැඳින්වූ ජනාවාස වර්ග දෙක අතර වෙනස කුමක්ද?", "ග්‍රාම යනු කෘෂිකාර්මික ගම් වන අතර නිගම යනු වෙළෙඳ නගර හෝ වෙළෙඳ ගම් වේ", "නිගම යනු හමුදා කඳවුරුය", "ග්‍රාම යනු මුහුදු වරායවල්ය", "දෙකම පාලු වනාන්තරය", "වෙළෙඳාම මුල් කරගත් නාගරික නොවන වෙළෙඳ මධ්‍යස්ථාන 'නිගම' ලෙස හැඳින්විණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ විශාලතම අභ්‍යන්තර නගරය වූ අනුරාධපුරයට 'ඇතුළුනුවර' සහ 'පිටනුවර' යනුවෙන් කොටස් දෙකක් තිබීමෙන් පෙනෙන්නේ කුමක්ද?", "ප්‍රාකාරවලින් වට වූ පාලන මධ්‍යස්ථානයත් ඉන් පිටත ආරාම හා ජනාවාසත් වෙන්ව සැලසුම් කර තිබූ බව", "සියලු ජනයා මාලිගාව ඇතුළේ විසූ බව", "පිටනුවර සතුරන්ට අයිතිව තිබූ බව", "නගරයේ සැලසුමක් නොතිබූ බව", "රාජකීය මාලිගා හා පරිපාලන ගොඩනැගිලි ඇතුළුනුවර තුළත් මහාවිහාරය ඇතුළු ආරාම පිටනුවරත් පිහිටියේය."),
    q(T, "අනුරාධපුර පුරාණ නගරයේ පිටත ප්‍රදේශවල වෙන වෙනම වෙන් කර තිබූ පොදු ස්ථාන මොනවාද?", "ආරාම සංකීර්ණ, වැව්, සුසාන භූමි සහ වෙළෙඳුන්ගේ වීදි", "කර්මාන්තශාලා සහ දුම්රියපොළ", "ක්‍රීඩාංගණ පමණක්", "කාර්මික ගබඩා පමණක්", "පණ්ඩුකාභය රජ සමයේ සිටම අනුරාධපුරය ක්‍රමවත් කලාපීය සැලැස්මකට අනුව ගොඩනැගී තිබුණි."),
    q(T, "පැරණි ලංකාවේ කෘෂිකාර්මික ආර්ථිකයේ ප්‍රධාන වගා කන්න දෙක හැඳින්වෙන්නේ කුමන නම්වලින්ද?", "යල කන්නය සහ මහ කන්නය", "වසන්ත කන්නය සහ ශීත කන්නය", "මෝසම් කන්නය සහ වියළි කන්නය", "පළමු හා අවසන් කන්නය", "ඊසානදිග මෝසමින් මහ කන්නයත් නිරිතදිග මෝසම හා වැව් ජලයෙන් යල කන්නයත් වගා කෙරිණි."),
    q(T, "පුරාණ සිංහල ගොවීන් එකම ඉඩමේ දියුණු ක්‍රමයට වසර පුරා 'මැද කන්නයක්' පවා වගා කළ බවට සාධක හමුවන්නේ කුමන ශිලා ලේඛනයෙන්ද?", "තෝණිගල සෙල්ලිපියෙන් (පිටදඩ හස, අකල හස, මැදේ හස)", "ගල්පොත ලිපියෙන්", "පනාකඩුව තඹ සන්නසින්", "සීගිරි කුරුටු ගීවලින්", "තෝණිගල ලිපියේ කන්න තුනක් (පිටදඩ, අකල හා මැදේ) වී වගා කළ බව සඳහන් වීමෙන් ජල සුලබතාව පෙනේ."),
    q(T, "පැරණි ගොවිතැනේදී පොහොර යෙදීම සඳහා ගොවීන් යොදාගත් ස්වාභාවික ක්‍රම මොනවාද?", "ගව පොහොර, කොළ පොහොර සහ පිදුරු පසට යට කිරීම", "රසායනික යූරියා පොහොර", "ප්ලාස්ටික් අපද්‍රව්‍ය", "ඛනිජ තෙල්", "පරිසර හිතකාමී කාබනික පොහොර හා පිදුරු දිරාපත් වීමට හැරීමෙන් පසේ සාරවත් බව රැක ගත්හ."),
    q(T, "පැරණි වාරි තාක්ෂණයේදී බිසෝකොටුවක ඇති ප්‍රධාන කොටස් තුන කවරේද?", "ඇතුළු වන කොටස (මොහොල/දොර), ගැඹුරු ළිඳ (බිසෝකොටුව) සහ පිටවන නළය", "රළපනාව, පිටවාන සහ වැව් පතුල", "වැව් කණ්ඩිය, නියර සහ පැල", "වතුර මල, පොකුණ සහ ළිඳ", "ගල් පුවරු හා ගඩොල්වලින් නිමවන ලද බිසෝකොටුව ජල පීඩනය අඩු කර වැව් බැම්ම සුරකී."),
    q(T, "ශ්‍රී ලංකාවේ පැරණි වාරිමාර්ග නිර්මාණ අධ්‍යයනය කළ විදේශීය ඉංජිනේරුවන් විස්මයට පත් වූ ප්‍රධාන කරුණ කුමක්ද?", "සැතපුමකට අඟල් කිහිපයක අතිශය සියුම් බෑවුම් මැන ඇළ මාර්ග කැණීමේ තාක්ෂණය", "යකඩ පාලම් තැනීම", "ඩීසල් පොම්ප භාවිතය", "කෘත්‍රිම වැසි ඇති කිරීම", "යෝධ ඇළ වැනි කිලෝමීටර 80කට වැඩි ඇළ මාර්ග ඉතා සියුම් මට්ටම් ගෙන තැනීම ලොව විශිෂ්ට ඉංජිනේරු හපන්කමකි."),
    q(T, "අනුරාධපුර යුගයේ සිටම පැවති 'වනගත පෙදෙස් ආරක්ෂා කිරීම' හා 'ජල පෝෂක වනාන්තර' රැකගැනීමේ වැදගත්කම කුමක්ද?", "වැව්වලට නිරන්තර ජල උල්පත් ලබා ගැනීම හා පාංශු ඛාදනය වැළැක්වීම", "වන සතුන් සියල්ල මරා දැමීම", "රජුට දර ලබා ගැනීමට පමණක්", "වතු වගාව ආරම්භ කිරීමට", "වැවක ඉහළ පෙදෙසේ 'තාවුල්ල' හා කඳුකර වනාන්තර රැකගැනීමෙන් වැවේ මඩ තැන්පත් වීම වැළැක්විණි."),
    q(T, "පැරණි ලංකාවේ 'උරුවෙල' නම් පැරණි වෙළෙඳ වරාය පිහිටා තිබුණේ කුමන ප්‍රදේශයේද?", "කලා ඔය මෝය ආසන්නයේ (පුත්තලම උතුරේ)", "ගාල්ලේ", "හම්බන්තොට", "මඩකලපුවේ", "උරුවෙල වරාය මුතු කිමිදීම හා බටහිර වෙරළේ වෙළෙඳ කටයුතු සඳහා ප්‍රසිද්ධ විය."),
    q(T, "දකුණු ලංකාවේ 'මහාගාම' (තිස්සමහාරාමය) ආශ්‍රිත වරායක් ලෙස කිරින්ද අසල පිහිටි පැරණි නැව් තොට කුමක්ද?", "කිරින්ද හා ගෝදපවත", "ජම්බුකෝලපට්ටන", "ගෝකණ්ණ", "මහාතිත්ථ", "රුහුණු රාජධානියේ අගනුවර වූ මහාගාමයට සමීපව ගොඩවාය හා කිරින්ද වරායන් පිහිටියේය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ සමාජයේ විවිධ වෘත්තිකයන් අතර 'කුම්භකාර' යනුවෙන් හැඳින්වූයේ කවුරුන්ද?", "මැටි වළං හා බඳුන් නිපදවූ කුඹල් ශිල්පීන්", "රන් ආභරණ තැනූ අය", "ඇඳුම් මැසූ අය", "ගොඩනැගිලි සැලසුම් කළ අය", "දෛනික පරිභෝජනයට මෙන්ම වෛද්‍ය හා ආගමික කටයුතුවලට මැටි බඳුන් නිපදවූ පිරිස කුම්භකාර නම් විය."),
    q(T, "පැරණි ලංකාවේ 'චිත්‍රකාර' හා 'වඩ්ඪකී' යනුවෙන් සෙල්ලිපි හා වංශකතාවල සඳහන් වන ශිල්පීන් කවුද?", "සිත්තරුන් සහ වඩු/ගොඩනැගිලි කාර්මික ශිල්පීන්", "ධීවරයන් සහ දඩයක්කරුවන්", "සෙබළුන් සහ නැවියන්", "බදු එකතු කරන්නන්", "රාජ මාලිගා, ස්තූප හා විහාර ඉදිකිරීමේදී වඩු හා ගල්වඩු ශිල්පීහු ප්‍රධාන කාර්යභාරයක් ඉටු කළහ."),
    q(T, "පැරණි සිංහල සමාජයේ වෛද්‍ය ක්‍රමය තුළ දියුණු 'ශල්‍ය වෛද්‍ය විද්‍යාවක්' පැවති බව තහවුරු වන්නේ කෙසේද?", "පොළොන්නරුව ආළාහන පිරිවෙන හා මිහින්තලේ රෝහල් කැණීම්වලින් ශල්‍ය උපකරණ හමුවීමෙන්", "ලන්දේසි රෝහල් වාර්තාවලින්", "චීන සිතියම්වලින්", "පෘතුගීසි පොත්වලින්", "කතුරු, පිහි, අඬු සහ බෙහෙත් ඔරු ආදිය පුරාවිද්‍යා කැණීම්වලින් හමු වී තිබේ."),
    q(T, "මහා වෙළෙඳ මාර්ග පද්ධතියක හරස් සන්ධි ලෙස පැරණි ලංකාවේ 'මහා මාර්ග' පැවති බව දැක්වෙන වංශකතා සාධකය කුමක්ද?", "රාජධානි අතර ඇත්, අස් හා රථ ගමන් කළ හැකි මාර්ග හා ගල් පාලම් ඉදිකර තිබීම", "කාපට් පාරවල් තිබීම", "විදුලි දුම්රිය තිබීම", "ගුවන් තොටුපළ තිබීම", "අනුරාධපුර මල්වතු ඔය හරහා ඇති පැරණි ගල් පාලම් නටබුන් මාර්ග ජාලය සනාථ කරයි."),
    q(T, "අනුරාධපුරයේ මල්වතු ඔය සහ යාන් ඔය හරහා පැරණි සිංහලයන් ඉදි කළ පාලම් විශේෂය නිමවා තිබුණේ කුමන ද්‍රව්‍යවලින්ද?", "විශාල කළුගල් කුළුණු හා ගල් පුවරුවලින්", "යකඩ සහ වානේවලින්", "කොන්ක්‍රීට්වලින්", "රබර් ලෑලිවලින්", "ගංවතුරට ඔරොත්තු දෙන සේ කළුගල් කණු මත දැවැන්ත ගල් පුවරු අතුරා ගල් පාලම් තැනූහ."),
    q(T, "පැරණි ලංකාවේ වරායන් වෙත පැමිණි විදේශීය වෙළෙඳුන් අතර 'පර්සියානුවන්', 'අරාබිවරුන්' සහ 'චීන ජාතිකයන්' බහුල වීමට ප්‍රධාන හේතුව කුමක්ද?", "ඉන්දියානු සාගරයේ නැගෙනහිර-බටහිර වෙළෙඳ හුවමාරු මධ්‍යස්ථානය ලෙස ලංකාව පිහිටීම", "යුරෝපයට පයින් යා හැකි වීම", "තෙල් ආකර තිබීම", "සිසිල් දේශගුණය", "සේද මාවතේ මුහුදු මාර්ගයේ ප්‍රධාන වෙළෙඳ නැවතුම ලංකාව විය."),
    q(T, "අනුරාධපුර යුගයේ රජවරුන් විසින් විදේශීය රටවල් සමඟ පැවැත්වූ තානාපති සබඳතාවලට නිදසුනක් වන්නේ කුමක්ද?", "භාතිකාභය රජු රෝමයට තානාපති පිරිසක් යැවීම හා සිරිමෙවන් රජු සමුද්‍රගුප්ත රජුට තෑගි යැවීම", "ඇමරිකාව සමඟ ගිවිසුම් ගැසීම", "ඕස්ට්‍රේලියාවට දූතයන් යැවීම", "බ්‍රසීලය සමඟ වෙළෙඳාම් කිරීම", "අනුරාධපුර පාලකයෝ රෝමය, ඉන්දියාව හා චීනය සමඟ මිත්‍රශීලී රාජ්‍ය තාන්ත්‍රික සබඳතා පැවැත්වූහ."),
    q(T, "කිත්සිරිමෙවන් රජුගේ සමයේ ඉන්දියාවේ සමුද්‍රගුප්ත අධිරාජ්‍යයාගෙන් අවසර ගෙන බුද්ධගයාවේ ඉදි කළ විශේෂ ස්ථානය කුමක්ද?", "ලාංකික වන්දනාකරුවන් හා භික්ෂූන් සඳහා ආරාමයක් (සංඝාරාමයක්)", "වෙළෙඳපොළක්", "නාවික කඳවුරක්", "බදු කාර්යාලයක්", "ඉන්දියාවේ බුද්ධගයාව වන්දනා කිරීමට යන ලාංකිකයන්ගේ පහසුවට රජු මෙම ආරාමය ඉදි කළේය."),
    q(T, "පැරණි ලංකාවේ 'ගව පාලනය' ආර්ථිකයේ වැදගත් කොටසක් වූයේ කුමන හේතූන් මතද?", "ගොවිතැනේදී සී සෑමට, ගොයම් පෑගීමට, ප්‍රවාහනයට හා කිරි නිෂ්පාදන ලබා ගැනීමට", "විදේශයන්ට මස් අපනයනය කිරීමට පමණක්", "ගව සම් කාසි සෑදීමට", "ගවයන් නැව් ඇදීමට යොදා ගැනීමට", "කෘෂිකාර්මික හා පෝෂණ කටයුතුවලදී ගව සම්පත ('පස්ගෝරස') ඉතා වැදගත් විය."),
    q(T, "පැරණි සමාජයේ විවාහ චාරිත්‍ර හා පවුල් ඒකකය තුළ දක්නට ලැබුණු ප්‍රධාන විවාහ ක්‍රම දෙක කුමක්ද?", "දීග විවාහය සහ බින්න විවාහය", "ලියාපදිංචි විවාහය පමණක්", "ව්‍යාපාරික විවාහය", "තාවකාලික විවාහය", "මනාලිය මනාලයාගේ නිවසට යාම දීග විවාහය වූ අතර මනාලයා මනාලියගේ නිවසේ පදිංචි වීම බින්න විවාහය විය."),
    q(T, "පැරණි ලංකාවේ බෞද්ධ සමාජය තුළ රජුට මෙන්ම සාමාන්‍ය ජනතාවටද සමාජ ආචාර ධර්ම ඉගැන්වීමේ ප්‍රධාන මූලාශ්‍රය කුමක් වීද?", "ජාතක කතා හා බෞද්ධ සූත්‍ර දේශනා", "පෘතුගීසි නීති සංග්‍රහය", "ලන්දේසි චාරිත්‍ර", "වෙළෙඳ ගිවිසුම්", "සිඟාලෝවාද සූත්‍රය හා පන්සිය පනස් ජාතක කතා සමාජයේ සදාචාර පදනම ගොඩනැගීය."),
    q(T, "පැරණි ලංකාවේ රාජ්‍ය ආදායම් මූලාශ්‍ර අතර වරාය තීරුබදුවලට අමතරව රජුට ආදායම් ලැබුණු ස්වාභාවික සම්පත් මොනවාද?", "මුතු කිමිදීම, මැණික් පතල් හා ලුණු ලේවායන්", "ගල් අඟුරු පතල්", "ඛනිජ තෙල් ළිං", "යුරේනියම් පතල්", "වටිනා මැණික්, මුතු හා ඇතුන් රාජ්‍ය භාණ්ඩාගාරයේ ප්‍රධාන ආදායම් මාර්ග විය."),
    q(T, "පැරණි රාජ්‍ය පාලන ක්‍රමයේදී ප්‍රාදේශීය පාලන ඒකක ලෙස 'රුහුණ' හා 'දක්ඛිණ දේශය' පාලනය කිරීම බොහෝ විට පැවරුණේ කා හටද?", "යුවරජුට (ආදිපාදවරුන්ට) හා රාජකීය කුමාරවරුන්ට", "විදේශීය තානාපතිවරුන්ට", "වෙළෙඳ නැව් කපිතාන්වරුන්ට", "ආරෝග්‍යශාලා වෛද්‍යවරුන්ට", "අනුරාධපුර අගභාගයේ දක්ඛිණ දේශය යුවරජුගේ පාලන ප්‍රදේශය ලෙස ක්‍රියාත්මක විය."),
    q(T, "රාජ්‍යත්වය හිමි නොවූ නමුත් රාජ්‍යයේ ඉහළම පරිපාලන සහායකයන් වූ කුමාරවරුන් හැඳින්වීමට භාවිත කළ පදවි නාම මොනවාද?", "උපරාජ, මහාපා (මහාදිපාද) සහ ආපා (ආදිපාද)", "සෙනෙවි හා ගමික", "පුරෝහිත හා ලේකම්", "මුදලි හා ආරච්චි", "මහාපා (ඊළඟ රජු) සහ ආපා යන පදවි රජ පවුලේ උරුමක්කාර කුමාරවරුන්ට පිරිනැමිණි."),
    q(T, "පැරණි ලංකාවේ විහාරාරාම ආශ්‍රිතව 'වැව්' හා 'කුඹුරු' පූජා කිරීමෙන් සමාජයට සිදු වූ ආර්ථික බලපෑම කුමක්ද?", "ගොවීන්ට ස්ථිර ජල සැපයුමක් ලැබීමත්, විහාර නඩත්තුව ස්වයංපෝෂිත වීමත්", "වගාවන් සම්පූර්ණයෙන් නතර වීම", "භික්ෂූන් වහන්සේලා වෙළෙඳුන් වීම", "රජයට බදු ලැබීම වැඩි වීම", "විහාරස්ථාන මගින් වැව් නඩත්තුව අධීක්ෂණය වූ අතර ගොවීහු නොකඩවා ගොවිතැන් කළහ."),
    q(T, "අනුරාධපුර යුගයේ චීනය සමඟ පැවති වෙළෙඳ සබඳතා තහවුරු කරන පුරාවිද්‍යාත්මක සාක්ෂියක් වන්නේ කුමක්ද?", "අනුරාධපුරය, පොළොන්නරුව හා මාන්තොටින් චීන සෙරමික් (පෝසිලේන්) බඳුන් හා කාසි හමුවීම", "චීන මහා ප්‍රාකාරයේ කොටසක් තිබීම", "චීන දුම්රිය හමුවීම", "චීන පාලකයන් ලංකාව යටත් කර ගැනීම", "සංග් හා මින්ග් රාජවංශ කාලවල චීන පෝසිලේන් කැබලි වරාය හා නගර කැණීම්වලින් හමුවේ."),
    q(T, "පැරණි ලංකාවේ 'උද්‍යාන කලාව' ඉතා දියුණු මට්ටමක පැවති බවට සාක්ෂි දරන අනුරාධපුරයේ පිහිටි රාජකීය උද්‍යානය කුමක්ද?", "රන්මසු උයන (මහමෙවුනා උයන හා නන්දන උයන සමඟ)", "පේරාදෙණිය උයන", "විහාරමහාදේවි උයන", "හග්ගල උයන", "ඉසුරුමුණිය අසල පිහිටි රන්මසු උයන පොකුණු, ජල මාර්ග හා විවේක මණ්ඩප සහිත විශිෂ්ට උද්‍යානයකි."),
    q(T, "ශ්‍රී ලංකාවේ පැරණි 'කැසිකිළි ගල්' (Urinal Stones) හා පවිත්‍රතා පද්ධති අධ්‍යයනය කිරීමෙන් හෙළි වන්නේ කුමක්ද?", "ආරාම සංකීර්ණවල උසස් සනීපාරක්ෂක ක්‍රම හා ජල පවිත්‍රකරණ තාක්ෂණය පැවති බව", "සෞඛ්‍ය පහසුකම් නොතිබූ බව", "පෘතුගීසි ගෘහ නිර්මාණ බව", "වැව් බැමි තැනූ බව", "අනුරාධපුරයේ පශ්චිමාරාමවල විසිතුරු කැටයම් සහිත ගල් සනීපාරක්ෂක පද්ධති හමුවේ."),
    q(T, "පැරණි සමාජයේ ජනයා විවිධ උත්සව හා සංස්කෘතික කටයුතුවලදී භාවිත කළ 'පංචතූර්ය නාදයට' අයත් භාණ්ඩ වර්ගීකරණය කුමක්ද?", "ආතත, විතත, විතතාතත, ඝන සහ සුසිර", "ගිටාර්, වයලීන, පියානෝ, බටනළා, බෙර", "තඹ, රිදී, රන්, යකඩ, ලෝකඩ", "හක්ගෙඩිය පමණක්", "සම සම් බෙර, තත් භාණ්ඩ, ලෝහ භාණ්ඩ හා සුසිර භාණ්ඩ ඇතුළත් පංචතූර්ය නාද සම්ප්‍රදාය පැවතුණි."),
    q(T, "පැරණි ග්‍රාමීය සමාජයේ විවිධ ගම් අතර හා ගම් තුළ වූ 'ගමේ වැව' මගින් ඉටු වූ සමාජයීය කාර්යභාරය කුමක්ද?", "ගොවිතැනට ජලය සැපයීම, ගෘහස්ථ ජල අවශ්‍යතා සපුරාලීම හා සාමූහික එකමුතුව ගොඩනැගීම", "නාවික හමුදා පුහුණු කිරීම", "කාර්මික අපද්‍රව්‍ය බැහැර කිරීම", "විදේශීය වෙළෙඳුන් නැවැත්වීම", "වැව් පාමුල ගමත්, ගොඩ බිමත්, වෙල් යායත් ගොඩනැගී ගැමියන්ගේ ආර්ථික හා සංස්කෘතික ජීවිතය බැඳුණි."),
    q(T, "අනුරාධපුර යුගයේ භාවිත කළ 'කහපණ' කාසිවලට අමතරව ගනුදෙනු පහසුව සඳහා පැවති කුඩා මුදල් ඒකකයක් කුමක්ද?", "මස්ස සහ අක", "සතය සහ ශත පහ", "ඩොලරය", "පවුම", "වටිනාකමින් අඩු දෛනික වෙළෙඳ ගනුදෙනු සඳහා කුඩා බරින් යුත් අක හා මස්ස කාසි භාවිත විය."),
    q(T, "පැරණි ලංකාවේ 'වනගත ගෝත්‍රික' හා 'ග්‍රාමීය කෘෂි' ජන කොටස් අතර පැවති සම්බන්ධතාව කෙබඳු වීද?", "මී පැණි, දඩ මස් හා වන ද්‍රව්‍ය සමඟ ලුණු, රෙදි හා යකඩ ආයුධ හුවමාරු කර ගැනීමේ සහජීවනයක්", "නිරන්තර සම්පූර්ණ යුද්ධ පමණක්", "කිසිදු සම්බන්ධයක් නොතිබීම", "විදේශිකයන් හරහා පමණක් ගනුදෙනු කිරීම", "වනවාසී ජනයා හා ගොවි ජනයා අන්‍යෝන්‍ය ආර්ථික හුවමාරු මගින් ජීවත් වූහ."),
    q(T, "රාජ්‍ය පාලනයේදී රජු සතු වූ 'සේසත' (සුදු කුඩය), 'ඔටුන්න', 'මඟුල් කඩුව' ආදිය හඳුන්වන්නේ කුමන නමකින්ද?", "පංච කකුධ භාණ්ඩ (රාජකීය අභිෂේක සංකේත)", "වෙළෙඳ භාණ්ඩ", "කෘෂි උපකරණ", "දානමය වස්තු", "චාමරය, ඔටුන්න, කඩුව, සේසත සහ රන් මිරිවැඩි යන පංච කකුධ භාණ්ඩ රාජ්‍යත්වයේ සංකේත විය."),
    q(T, "පැරණි ලංකාවේ වියළි කලාපයේ ප්‍රධාන ගංගාවක් වන මහවැලි ගඟ හරස් කර ඇළහැර අමුණ බැඳීමෙන් ජලය රැගෙන ගිය ප්‍රධාන වැව් මොනවාද?", "මින්නේරිය, කවුඩුල්ල, කන්තලේ සහ ගිරිතලේ", "තිස්ස වැව සහ යෝධ වැව", "පරාක්‍රම සමුද්‍රය පමණක්", "නුවර වැව සහ නාච්චදූව", "අඹන් ගඟ (මහවැලි අතු ගංගාව) හරස් කර ඇළහැරින් ජලය මින්නේරිය හා කන්තලේ දක්වා ගෙන ගියේය."),
    q(T, "අනුරාධපුර යුගයේ දකුණු ලංකාවේ වාරි පද්ධති අතර ප්‍රකට 'තිස්ස වැව', 'යෝධ වැව (මන්නාරම)' සහ 'නාච්චදූව' වැව ඉදි කළ අරමුණ කුමක්ද?", "නියං සමයේ වී වගාවට හා ජනාවාසවලට අඛණ්ඩ ජලය සැපයීම", "මුහුදු ජලය ගබඩා කිරීම", "මාළු ඇල්ලීම පමණක්", "විදේශ නැව් නැංගුරම් ලෑම", "වියළි කලාපයේ අනිත්‍ය වර්ෂාපතනය ජය ගැනීමට මෙම මහා ජලාශ තැනිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'වැව් ශිෂ්ටාචාරය' පිළිබඳව ප්‍රකට කියමනක් වන 'අහසින් වැටෙන එකදු දිය බිඳක්වත් මිනිසාගේ ප්‍රයෝජනයට නොගෙන මුහුදට නොයැවිය යුතුය' යන්න කුමන රජුට ආරෝපණය වේද?", "මහා පරාක්‍රමබාහු රජුට", "වසභ රජුට", "පණ්ඩුකාභය රජුට", "ධාතුසේන රජුට", "මහා පරාක්‍රමබාහු රජු ජල සම්පත උපරිමයෙන් කළමනාකරණය කිරීමේ ප්‍රතිපත්තිය මෙලෙස ප්‍රකාශ කළේය."),
    q(T, "පැරණි ලංකාවේ 'නගර සැලසුම්කරණයේදී' නගරයක් වටා දිය අගලක් හා පවුරක් ඉදිකිරීමේ ප්‍රධාන අරමුණ කුමක් වීද?", "සතුරු ආක්‍රමණවලින් නගරය ආරක්ෂා කර ගැනීම", "පිහිනුම් තරඟ පැවැත්වීම", "වෙළෙඳ නැව් ගොඩබෑම", "ජලවිදුලිය නිපදවීම", "අනුරාධපුරය, සීගිරිය හා පොළොන්නරුව යන නගරවල ආරක්ෂාවට පවුරු හා දිය අගල් තනා තිබුණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ කෘෂිකර්මාන්තයේදී 'පැරණි අමුණක්' (Weir / Dam) තැනීමේදී භාවිත කළ ප්‍රධාන ද්‍රව්‍ය මොනවාද?", "විශාල ගල් කුට්ටි, දැව හා මැටි බදාම", "වීදුරු හා ප්ලාස්ටික්", "වානේ පයිප්ප", "තාර සහ කාපට්", "ගඟේ ජල ප්‍රවාහයට ඔරොත්තු දෙන සේ එකට බැඳි ගල් පුවරු යොදා ඇළහැර, කළිඟු ආදී අමුණු තැනූහ."),
    q(T, "මහාතිත්ථ වරාය ආශ්‍රිතව වෙළෙඳ කටයුතු කළ දේශීය හා විදේශීය වෙළෙඳුන් අතර සිදු වූ භාණ්ඩ හුවමාරුවේදී ආනයනය කළ ප්‍රධාන ද්‍රව්‍ය මොනවාද?", "සේද රෙදි, පෝසිලේන්, වීදුරු භාණ්ඩ, රන් රිදී හා අශ්වයන්", "තේ සහ කෝපි", "මුතු හා කුරුඳු පමණක්", "යන්ත්‍රෝපකරණ", "චීන පෝසිලේන්, රෝම වීදුරු භාණ්ඩ හා සින්ධු අශ්වයන් ලංකාවට ආනයනය කළ ප්‍රධාන භාණ්ඩ විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ආගමික සංස්ථාව හා රාජ්‍ය පාලනය අතර පැවති සම්බන්ධතාව හැඳින්විය හැක්කේ කෙසේද?", "අන්‍යෝන්‍ය වශයෙන් එකිනෙකා ආරක්ෂා කර ගන්නා සහයෝගී බැඳීමක් ලෙස", "සතුරු විරෝධී බැඳීමක් ලෙස", "සම්පූර්ණයෙන් වෙන් වූ දෙපාර්ශ්වයක් ලෙස", "රජු ආගම තහනම් කළ ක්‍රමයක් ලෙස", "රජු සසුන රැකි අතර මහා සංඝරත්නය රජුට ජනතා සහයෝගය හා උපදේශනය ලබා දුන්නේය."),
    q(T, "පැරණි ග්‍රාමීය සමාජයේ ජනයා තම දරුවන්ට සිප් සතර මෙන්ම 'සාම්ප්‍රදායික කර්මාන්ත' හුරු කළේ කෙසේද?", "පරම්පරාගත පවුල් වෘත්තීය පුහුණුව හා ගුරුකුල ක්‍රමය මගින්", "විශ්වවිද්‍යාල උපාධි මගින්", "විදේශීය පාඨමාලා මගින්", "මුද්‍රිත පොත් කියවීමෙන් පමණක්", "කම්මල්, වඩු, කුඹල් හා වෛද්‍ය වැනි ශිල්ප පරම්පරාවෙන් පරම්පරාවට ප්‍රායෝගිකව උගන්වන ලදී."),
    q(T, "අනුරාධපුර යුගයේ සමාජයේ සතුන්ට හා පරිසරයට දැක්වූ කරුණාව පෙන්නුම් කරන රාජකීය සේවාවක් කුමක්ද?", "සතුන් සඳහාද වෛද්‍යවරුන් හා ආරෝග්‍යශාලා පිහිටුවීම (බුද්ධදාස රජු)", "සතුන් කූඩු කර ප්‍රදර්ශනය කිරීම", "වන සතුන් අපනයනය කිරීම", "සියලු සතුන් දඩයම් කිරීම", "බුද්ධදාස රජු මිනිසුන්ට මෙන්ම ඇතුන් හා අශ්වයන් වැනි සතුන්ටද වෛද්‍ය ප්‍රතිකාර සැලසීය."),
    q(T, "පැරණි ලංකාවේ 'වෙළෙඳ සංගම්' (Guilds) සතුව තිබූ විශේෂ බලතලයක් ලෙස තෝණිගල ලිපියෙන් පෙනී යන්නේ කුමක්ද?", "ජනතාවගෙන් ධාන්‍ය තැන්පතු භාරගෙන පොලී ගෙවීමේ මූල්‍ය කටයුතු සිදු කිරීම", "හමුදාවන් පාලනය කිරීම", "රජු පත් කිරීම", "විදේශ යුද්ධ ප්‍රකාශ කිරීම", "වෙළෙඳ සංගම් කෙරෙහි සමාජයේ විශ්වාසය හා ස්ථාවරත්වය තෝණිගල ලිපියෙන් පැහැදිලි වේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ප්‍රධාන වරායන් වූ මහාතිත්ථ හා ගෝකණ්ණ අතර සම්බන්ධතාව පැවතීම වැදගත් වූයේ ඇයි?", "විවිධ මෝසම් සුළං කාලවලදී නැව්වලට ආරක්ෂිතව ගොඩබැසීමට හැකි වීම", "එකම ගමේ පිහිටා තිබීම", "ධීවරයන්ට පමණක් වෙන් වීම", "නැව් සෑදීම පමණක් සිදු වීම", "නිරිතදිග හා ඊසානදිග මෝසම් සුළං අනුව බටහිර හා නැගෙනහිර වරායන් විකල්ප වශයෙන් භාවිත විය."),
    q(T, "පැරණි ලංකාවේ රාජ්‍ය නිලධාරීන් අතර 'නගර ගුත්තික'ට අමතරව අධිකරණ හා පරිපාලන කටයුතු කළ පදවියක් වන්නේ කුමක්ද?", "සභාපති හෝ විනිශ්චයකාර (ධම්මදේසක / වෝහාරික)", "කපිතාන්", "ගවර්නර්", "පෝස්ට්මාස්ටර්", "වෝහාරිකතිස්ස රජු නීතිය හා අධිකරණය ප්‍රතිසංස්කරණය කරමින් අඟපසඟ කැපීමේ දඬුවම් අහෝසි කළේය."),
    q(T, "අනුරාධපුර යුගයේ ශාරීරික දඬුවම් වෙනුවට දඩ ගැසීම වැනි මානුෂීය නීති ක්‍රම හඳුන්වා දුන් කීර්තිමත් රජු කවුද?", "වෝහාරිකතිස්ස රජු (ක්‍රි.ව. 214 - 236)", "එළාර රජු", "කාශ්‍යප රජු", "මහසෙන් රජු", "නීති විශාරදයෙකු වූ වෝහාරිකතිස්ස රජු කෲර ශාරීරික හිංසන දඬුවම් නතර කළේය."),
    q(T, "පැරණි ලංකාවේ 'වන සංරක්ෂණය' මෙන්ම වැව්වලට ඉහළින් කුඹුරු වගා නොකර වනාන්තර ඉතිරි කිරීමේ පාරිසරික රීතිය කුමක්ද?", "වැව් ඉස්මත්ත හෙවත් ගස්ගොම්මන ආරක්ෂා කිරීම", "පිටවාන කඩා දැමීම", "සියලු ගස් කපා පිළිස්සීම", "රළපනාව ගලවා දැමීම", "ගස්ගොම්මන සුළං බාධකයක් ලෙස හා පාංශු ඛාදනය වැළැක්වීමට වැව් ඉස්මත්තේ රැක ගැනිණි."),
    q(T, "වැව්වල ජලය පිරිසිදුව තබා ගැනීමට හා මඩ වැවට ගලා ඒම වැළැක්වීමට වැව් ඉහළ පෙදෙසේ සැකසූ ස්වාභාවික පෙරණය කුමක්ද?", "කට්ටකාඩුව සහ ඉස්වැටිය / පෙරහන", "බිසෝකොටුව", "සොරොව් කට", "වෙල් යාය", "කට්ටකාඩුව වැව් බැම්මෙන් කාන්දු වන ජලයේ ලවණතාව උරා ගැනීමටත් ඉස්වැටිය මඩ රඳවා ගැනීමටත් ඉවහල් වේ."),
    q(T, "පැරණි ලංකාවේ රාජ්‍ය පාලන ක්‍රමයේදී 'ප්‍රාදේශීය රජවරුන්' (උදා — රුහුණේ හා කැලණියේ) පාලනය කළ අවස්ථාවලදී ප්‍රධාන අගනුවර රජුට දැක්වූ සම්බන්ධතාව කුමක්ද?", "අනුරාධපුර මහරජුගේ අධිපතිත්වය පිළිගෙන අවනතව පාලනය ගෙන යාම", "සෑම දිනකම අනුරාධපුරයට පහර දීම", "විදේශ රටවලට රට විකිණීම", "බදු ගෙවීම සම්පූර්ණයෙන් ප්‍රතික්ෂේප කිරීම", "රුහුණු හා මලය පාලකයෝ බොහෝ විට අනුරාධපුරයේ මහා රජුගේ නායකත්වය පිළිගත්හ."),
    q(T, "පැරණි සිංහල ජනාවාස ව්‍යාප්ත වූ වියළි කලාපයේ ප්‍රධාන වශයෙන් වැඩි ජනගහනයක් ජීවත් වීමට හේතුව කුමක්ද?", "විශාල තැනිතලා බිම්, සරු රතු-දුඹුරු පස සහ වී වගාවට හිතකර දේශගුණය", "අධික හිම පතනය", "තෙත් කලාපයේ මිනිසුන්ට ජීවත් වීමට නොහැකි වීම", "කර්මාන්තශාලා බහුල වීම", "වියළි කලාපයේ වනාන්තර එළි කිරීම පහසු වීමත් හිරු එළිය බහුල වීමත් කෘෂිකර්මයට ඉතා සුදුසු විය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ග්‍රාමීය වැවක්' සහ 'මහා වැවක්' අතර පැවති ප්‍රධාන වෙනස කුමක්ද?", "ග්‍රාමීය වැව ගමේ ගොවීන් තනි ගමක ප්‍රයෝජනයට තැනූ අතර මහා වැව රාජ්‍ය අනුග්‍රහයෙන් විශාල ප්‍රදේශයකට ජලය සැපයීය", "ග්‍රාමීය වැව මුහුදු ජලයෙන් පිරිණි", "මහා වැව කුඩා පොකුණකි", "වෙනසක් නොතිබුණි", "වසභ හා මහසෙන් වැනි රජවරු තැනූ මහා වැව් අමුණු මගින් කුඩා ග්‍රාමීය වැව් පද්ධතිද පෝෂණය විය."),
    q(T, "අනුරාධපුර යුගයේ සමාජයේ දක්නට ලැබුණු 'දාස ක්‍රමය' යුරෝපීය වහල් ක්‍රමයෙන් වෙනස් වන්නේ කෙසේද?", "බෞද්ධ සමාජයේ මානුෂීය සැලකිල්ල හිමි වීම හා මුදල් ගෙවා නිදහස් වීමේ අවස්ථා තිබීම", "දාසයන්ට ජීවිතාන්තය දක්වා හිංසා කිරීම", "දාසයන් නැව්වල දම්වැල් දමා තැබීම", "දාසයන් කිසිදා නොසිටීම", "සමන්තපාසාදිකාව හා සෙල්ලිපි අනුව දාසයන්ට නීතිමය ආරක්ෂාව හා විමුක්තිය ලැබීමේ ක්‍රම තිබුණි."),
    q(T, "අනුරාධපුර යුගයේ චීනය සමඟ පැවති සංස්කෘතික සබඳතාවල ප්‍රතිඵලයක් ලෙස ලංකාවේ සිට චීනයට වැඩම කළේ කවුරුන්ද?", "දේවසාරා තෙරණිය ඇතුළු සිංහල භික්ෂුණී පිරිස", "විජය කුමරු", "කාශ්‍යප රජු", "රොබට් නොක්ස්", "ක්‍රි.ව. 5 වන සියවසේ ශ්‍රී ලාංකික භික්ෂුණීන් වහන්සේලා චීනයේ භික්ෂුණී ශාසනය පිහිටුවීමට වැඩම කළහ."),
    q(T, "පැරණි ලංකාවේ ආර්ථිකයේ 'කිතුල් කර්මාන්තය', 'මී පැණි රැස් කිරීම' හා 'උක් වගාව' පැවති බවට සාධක සපයන්නේ මොනවාද?", "වංශකතා හා අටුවා ග්‍රන්ථවල එන ආහාරපාන හා පැණි/සකුරු පූජා විස්තර", "බ්‍රිතාන්‍ය තේ වතු වාර්තා", "පෘතුගීසි කාලතුවක්කු ලැයිස්තු", "රෝම සිතියම්", "දුටුගැමුණු රජු විසින් රුවන්වැලිසෑයේ වැඩ කළ අයට පැණි හා හකුරු දුන් බව මහාවංශයේ සඳහන් වේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ කෘෂිකර්මය මත පදනම් වූ ආර්ථිකය ස්ථාවරව පවත්වාගෙන යාම සඳහා රජය විසින් ඉටු කළ ප්‍රධාන වගකීම කුමක්ද?", "මහා වාරිමාර්ග ඉදිකිරීම, ප්‍රතිසංස්කරණය කිරීම හා නියඟ කාලවලදී ධාන්‍ය සුරැකීම", "සියලු ගොවීන්ට නගරයට යන ලෙස නියෝග කිරීම", "වී වගාව තහනම් කිරීම", "විදේශීය හාල් පමණක් ගෙන්වීම", "ජනතාවගේ ආහාර සුරක්ෂිතතාව තහවුරු කිරීම රජුගේ ප්‍රධාන රාජ්‍ය වගකීමක් විය."),
    q(T, "පැරණි ගම්මානයක 'වැව් තාවුල්ල' (Tank Catchment Bed) ආශ්‍රිතව වගා නොකිරීමට හේතු වූ පාරිසරික කාරණය කුමක්ද?", "ජලය අපවිත්‍ර වීම හා රොන්මඩ වැවට ගලා ඒම වැළැක්වීම", "එය රජුගේ වාසස්ථානය වීම", "සතුන්ට පමණක් අයිති වීම", "මුහුදු ජලය ගලා ඒම", "තාවුල්ල යනු වැවේ ජල පෝෂක පෙදෙස වන බැවින් එය වනාන්තරයක් ලෙස රැක ගැනිණි."),
    q(T, "වියළි කලාපයේ පැරණි ගොවීන් ගෘහස්ථ ජල අවශ්‍යතා සඳහා භාවිත කළ කුඩා ජල සංචිත ක්‍රමය කුමක්ද?", "පින්තාලිය සහ දිය උල්පත් ළිං", "විදුලි මෝටර් ළිං", "ජල ටැංකි ලොරි", "නල ජල සැපයුම්", "ගම්මානවල ජනතාව පානීය ජලය සඳහා වැවට අමතරව උල්පත් ළිං භාවිත කළහ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණි කෘෂි සමාජයේ 'කුරක්කන්' වගාව ආහාර සුරක්ෂිතතාවට වැදගත් වූයේ ඇයි?", "දීර්ඝ කාලයක් නරක් නොවී අටුවල ගබඩා කර තැබිය හැකි බැවින්", "එයින් රෙදි නිපදවිය හැකි බැවින්", "එය මත්පැන් වර්ගයක් බැවින්", "එය මිල අධික සුඛෝපභෝගී භාණ්ඩයක් බැවින්", "නියං කාලවලදී පරිභෝජනයට කුරක්කන් වසර ගණනාවක් වී අටුවල තබා ගත හැකි විය."),
    q(T, "පැරණි ලංකාවේ 'වී අටුව' (Paddy Barn) ගොඩනගා තිබූ විශේෂ වාස්තු විද්‍යාත්මක ලක්ෂණය කුමක්ද?", "බිමෙන් ඔසවා ගල් කුළුණු මත මීයන් හා වේයන්ගෙන් ආරක්ෂා වන සේ තැනීම", "වීදුරුවලින් පමණක් තැනීම", "මුහුද ආසන්නයේ තැනීම", "පොළොව යට ගැඹුරට හෑරීම", "ධාන්‍ය තෙතමනයෙන් හා කෘමීන්ගෙන් ආරක්ෂා කිරීමට ගල් කණු මත ලී සහ මැටිවලින් අටු තැනීය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'කුල ක්‍රමය' යුරෝපයේ මෙන් නොව ප්‍රධාන වශයෙන් පදනම් වී තිබුණේ කුමක් මතද?", "වෘත්තීය ශ්‍රම විභේදනය සහ රාජකාරි වගකීම් මත", "සමෙහි පැහැය මත පමණක්", "යුද හමුදා තරාතිරම මත", "විදේශීය භාෂා දැනුම මත", "ගොවිතැන, ලෝහ, මැටි, රෙදි විවීම ආදී වෘත්තීන් පදනම් කරගත් සමාජ සංවිධානයක් පැවතුණි."),
    q(T, "පැරණි රාජ්‍ය පාලනයේදී 'රාජකාරි ක්‍රමය' යනු කුමක්ද?", "ඉඩම් භුක්තිය වෙනුවෙන් රජයට හෝ විහාරයට යම් සේවයක් ඉටු කිරීමේ වගකීම", "මුදල් පමණක් අය කිරීම", "සෑම පුරවැසියෙකුම හමුදාවට බැඳීම", "නගර පිරිසිදු කිරීම පමණක්", "ඉඩම භුක්ති විඳින්නා ඒ වෙනුවෙන් නියමිත රාජකාරිය ඉටු කිරීම සාම්ප්‍රදායික ක්‍රමය විය."),
    q(T, "පැරණි ලංකාවේ 'ලුණු' නිෂ්පාදනය හා වෙළෙඳාම සම්බන්ධයෙන් හම්බන්තොට හා පුත්තලම වැදගත් වූයේ ඇයි?", "ස්වාභාවික ලේවායන් බහුලව පිහිටා තිබීම හා රට අභ්‍යන්තරයට ලුණු සැපයීම", "එහි විශාල ගල් අඟුරු පතල් තිබීම", "තේ වතු පිහිටා තිබීම", "සීතල දේශගුණයක් පැවතීම", "හම්බන්තොට හා පුත්තලම ලේවායන්ගෙන් තවලම් මගින් රට පුරා ලුණු බෙදා හැරිණි."),
    q(T, "පැරණි සිංහල සමාජයේ 'තවලම' යනු කුමක්ද?", "භාණ්ඩ පටවන ලද ගවයන් හෝ බූරුවන් පේළියක් මගින් සිදු කළ වෙළෙඳ ගමනාගමනය", "මුහුදු නැව් සමූහයක්", "දුම්රියක්", "ගංගාවක පාවෙන දැව පාලමක්", "කඳුකරය හා පහතරට අතර ලුණු, වියළි මස්, කුළුබඩු ප්‍රවාහනය කළේ තවලම් මගිනි."),
    q(T, "පැරණි ලංකාවේ 'අත්කම් හා පිත්තල කර්මාන්තය' සඳහා ප්‍රකට වූ දිවයිනේ ප්‍රදේශයක් වන්නේ කුමක්ද?", "මහනුවර සහ මධ්‍යම කඳුකර ප්‍රදේශ", "යාපනය පමණක්", "කොළඹ වරාය", "මන්නාරම දුපත", "පිත්තල, තඹ හා රිදී කැටයම් කර්මාන්තය පරම්පරාගත ශිල්පීන් අතින් දියුණු විය."),
    q(T, "පැරණි කෘෂි සමාජයේ 'කෙත' සහ 'හේන' අතර පැවති ප්‍රධාන භූගෝලීය වෙනස කුමක්ද?", "කෙත මඩ ගොවිතැන වන අතර හේන ගොඩ බිමේ වර්ෂා ජලයෙන් කරන වගාවකි", "කෙතේ කුරක්කන් පමණක් වැවීම", "හේනේ මෝටර් රථ ධාවනය කිරීම", "දෙකම එකම ආකාරයේ වගාවක් වීම", "මඩ ගොවිතැනින් ප්‍රධාන ආහාරය වූ සහල්ද හේන් ගොවිතැනින් අතිරේක ධාන්‍ය හා එළවළුද ලැබිණි."),
    q(T, "පැරණි ලංකාවේ රෙදිපිළි නිෂ්පාදනය සඳහා කපු වගා කළ ප්‍රධාන ප්‍රදේශ මොනවාද?", "වියළි කලාපයේ හේන් බිම් (රුහුණ හා රජරට)", "නුවරඑළිය කඳු මුදුන්", "ගාලු වෙරළ තීරය", "කළුතර වගුරු බිම්", "කපු වගා කර නූල් කටින ලද බවට පුරාවිද්‍යා කැණීම්වලින් තහවුරු වේ."),
    q(T, "පැරණි ලංකාවේ භාවිත වූ 'යකඩ උදුන්'වල වාතය සැපයීමට ස්වාභාවික මෝසම් සුළං භාවිත කිරීමේ වාසිය කුමක්ද?", "අධික උෂ්ණත්වයක් (සෙල්සියස් 1200°C ට වැඩි) අඛණ්ඩව ලබා ගෙන වානේ නිපදවීමට හැකි වීම", "විදුලිය ඉතිරි වීම", "සීතල සුළං ලබා ගැනීම", "වැසි ජලය උණු කිරීම", "සමනලවැව උදුන් මෝසම් සුළඟ යොදා ගනිමින් වානේ නිපදවූ ලොව මුල්ම තාක්ෂණයකි."),
    q(T, "පැරණි සමාජයේ රජවරුන් සහ ප්‍රභූන් විසින් 'කළිඟු අමුණ' හා 'ඇළහැර අමුණ' වැනි දැවැන්ත වාරි නිර්මාණ ඉදිකිරීමට යෙදවූ ශ්‍රමය කුමක්ද?", "ගැමි ජනතාවගේ සාමූහික ශ්‍රමය හා දක්ෂ ගල්වඩු/පෙදරේරු ශිල්පීන්ගේ තාක්ෂණය", "විදේශීය යන්ත්‍ර සූත්‍ර", "වහලුන් පමණක්", "මුද්‍රිත සැලසුම්", "ගල් කැපීම, මට්ටම් ගැනීම හා බැමි බැඳීම දේශීය ශිල්පීන්ගේ නිපුණතාවෙන් සිදු විය."),
    q(T, "පැරණි සමාජයේ කෘෂිකාර්මික වාරි පද්ධතියක 'සොරොව්ව' (Sluice) පිහිටුවා තිබූ ස්ථාන කීයක් දැකිය හැකිද?", "ගොඩ සොරොව්ව සහ මඩ සොරොව්ව", "එක් සොරොව්වක් පමණි", "පිටවාන අසල පමණි", "වැව මැද පමණි", "ජලය මුදා හැරීමට ගොඩ සොරොව්වත් වැවේ මඩ ඉවත් කිරීමට මඩ සොරොව්වත් භාවිත විය."),
    q(T, "පැරණි සිංහල සමාජයේ 'කමත' (Threshing floor) ආශ්‍රිතව භාවිත වූ විශේෂ භාෂාව හැඳින්වෙන්නේ කුමන නමකින්ද?", "කමත් භාෂාව (ගොවි බස)", "ඉංග්‍රීසි භාෂාව", "සංස්කෘත ශ්ලෝක", "පාලි ගාථා පමණක්", "අවතාර හා අශුභ දේවලින් ධාන්‍ය ආරක්ෂා කර ගැනීමේ විශ්වාසය මත කමත් බස භාවිත විය."),
    q(T, "කමත් භාෂාවේදී 'වී' සඳහා භාවිත කළ ගෞරවනීය වචනය කුමක්ද?", "බෝගත හෝ මුතු", "පස්", "මැටි", "ගල්", "ධාන්‍ය කෙරෙහි දැක්වූ ගෞරවය නිසා කමතේදී වෙනම සුබ වචන යොදා ගැනිණි."),
    q(T, "පැරණි සමාජයේ 'අලුත් සහල් මංගල්‍යය' පවත්වනු ලැබුවේ කුමන අරමුණක් වෙනුවෙන්ද?", "අස්වැන්නේ පළමු කොටස ශ්‍රී මහා බෝධියට හා බුදුරදුන්ට පූජා කර සෙත් පැතීමට", "ධාන්‍ය විකිණීමට පමණක්", "විදේශිකයන්ට සංග්‍රහ කිරීමට", "බදු ගෙවීමට", "අනුරාධපුර ජය ශ්‍රී මහා බෝධීන් වහන්සේ වෙත අලුත් සහල් පූජා කිරීම අදටත් පැවතෙන චාරිත්‍රයකි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ජනාවාසවල සාමාජිකයන් අතර පැවති ආරවුල් විසඳීමට ගමේ වැඩිහිටියන් රැස් වූ සභාව කුමක්ද?", "ගම් සභාව (ග්‍රාම සභාව)", "රාජකීය උසාවිය", "දිසා අධිකරණය", "හමුදා විනිශ්චය සභාව", "ගමේ ප්‍රශ්න ගමේදීම සමථයකට පත් කර ගැනීමට ගම් සභාව ඉවහල් විය."),
    q(T, "පැරණි ලංකාවේ 'වෙළෙඳ නීති' උල්ලංඝනය කළ අයට බදුල්ල ටැම් ලිපිය අනුව පැනවූ දඬුවම් මොනවාද?", "දඩ ගැසීම සහ වෙළෙඳ බලපත්‍ර අහෝසි කිරීම", "මරණ දඬුවම පමණක්", "පිටුවහල් කිරීම", "සිරගත කිරීම", "හෝපිටිගමු වෙළෙඳපොළේ හොර මිනුම් භාවිත කළ අයට දඩ නියම කළ බව එහි සඳහන් වේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ භාවිත වූ 'මිනුම් උපකරණ' අතර ධාන්‍ය මනින ලීයෙන් කළ භාණ්ඩය කුමක්ද?", "ලහස්ස (කුරුණිය)", "මීටර් කෝදුව", "ඩිජිටල් තරාදිය", "වීදුරු බීකරය", "ලීයෙන් සැකසූ ලහස්ස හෙවත් කුරුණිය මගින් ධාන්‍ය මැනීම සිදු කෙරිණි."),
    q(T, "පැරණි ලංකාවේ කෘෂිකාර්මික ජනාවාස පද්ධතියේ 'ගව මඩුව' සහ 'ගාල' පිහිටුවා තිබුණේ කොහේද?", "නිවසට නුදුරින් ගොඩ ඉඩමේ ආරක්ෂිත ස්ථානයක", "වැව පතුලේ", "කුඹුර මැද පමණක්", "නගරයේ පමණක්", "රාත්‍රියේ වන සතුන්ගෙන් ගවයන් ආරක්ෂා කර ගැනීමට ගාල සකසා තිබුණි."),
    q(T, "පැරණි ලංකාවේ ගොවීන් වන සතුන්ගෙන් වගාව ආරක්ෂා කර ගැනීමට භාවිත කළ පරිසර හිතකාමී ක්‍රම මොනවාද?", "පැල් රැකීම, ටකරන් නාද කිරීම, හුළුඑළි දැල්වීම හා දඬුවැට බැඳීම", "විෂ රසායන දැමීම", "විදුලි වැටවල් දැමීම", "වෙඩි තැබීම", "සතුන් නොමරා පළවා හැරීමේ අවිහිංසාවාදී උපක්‍රම පැරණි ගොවියා භාවිත කළේය."),
    q(T, "පැරණි ලංකාවේ 'පැල් කවි' ගායනා කිරීමේ ප්‍රධාන අරමුණ කුමක් වීද?", "රාත්‍රියේ නිදිමත දුරු කර ගැනීම හා තනිකම මකා ගනිමින් වන සතුන් පළවා හැරීම", "සංගීත තරඟ ජය ගැනීම", "රජුට ප්‍රශස්ති කීම", "මුදල් ඉපයීම", "ගොවියා හේන් පැලේ සිට තමාගේ දුක් මහන්සිය හා ස්වභාවධර්මය කවියට නැඟුවේය."),
    q(T, "පැරණි ලංකාවේ 'කරත්ත කවි' හා 'පාරු කවි' බිහිවීමට බලපෑ සමාජ පසුබිම කුමක්ද?", "භාණ්ඩ ප්‍රවාහනයේ යෙදුණු ගැල්කරුවන් හා පාරුකරුවන්ගේ දීර්ඝ ගමන් විඩාව නිවා ගැනීම", "පාසල් විභාග සඳහා", "රාජසභා නාට්‍ය සඳහා", "විදේශිකයන් සතුටු කිරීමට", "කැලෑබද මාවත්වල හා ගංගාවල ගමන් ගත් ප්‍රවාහකයන් තම අත්දැකීම් කවියට නැඟූහ."),
    q(T, "පැරණි සමාජයේ 'බෙහෙත් ඔරු' නිර්මාණය කර තිබුණේ කුමන ද්‍රව්‍යයකින්ද?", "කළුගලින් මිනිස් සිරුරේ හැඩයට කුහරයක් හෑරීමෙන්", "ප්ලාස්ටික්වලින්", "තහඩුවලින්", "සිමෙන්තියෙන්", "මිහින්තලේ, අනුරාධපුරය හා මැදිරිගිරිය රෝහල්වල ගල් බෙහෙත් ඔරු දක්නට ඇත."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ආයුර්වේද වෛද්‍ය ක්‍රමය' පදනම් වී තිබූ ප්‍රධාන ත්‍රිදෝෂ මූලධර්මය කුමක්ද?", "වාත, පිත සහ සෙම (කඵ)", "රත්, නිල්, කහ", "උණුසුම, ශීතල, තෙතමනය", "වායුව, ජලය, ගින්න", "ශරීරයේ වා, පිත්, සෙම් සමතුලිතතාව රැකීමෙන් නිරෝගීභාවය ලැබෙන බව පිළිගැනුණි."),
    q(T, "පැරණි සිංහල රජවරුන් විසින් පත් කළ 'මහා වෙදනා' (Chief Physician) සතු වූ වගකීම කුමක්ද?", "රජ පවුලේ සෞඛ්‍යය මෙන්ම දිවයිනේ වෛද්‍ය පාලනය අධීක්ෂණය කිරීම", "හමුදා මෙහෙයවීම", "බදු එකතු කිරීම", "නැව් තැනීම", "වෛද්‍ය අධ්‍යක්ෂවරයා ලෙස මහා වෙදනා තනතුර රාජසභාවේ උසස් තනතුරක් විය."),
    q(T, "පැරණි සමාජයේ විවිධ කුල හා වෘත්තිකයන් අතර පැවති සබඳතාවේ විශේෂත්වය කුමක්ද?", "අන්‍යෝන්‍ය වශයෙන් එකිනෙකාගේ සේවය මත යැපුණු ආර්ථික සහයෝගීතාවක් වීම", "නිරන්තර යුද්ධ පැවතීම", "එකිනෙකා නොදැක ජීවත් වීම", "විදේශිකයන් පමණක් සම්බන්ධ වීම", "ගමේ සෑම වෘත්තිකයෙකුගේම සේවය ගමේ පැවැත්මට අත්‍යවශ්‍ය විය."),
    q(T, "පැරණි ලංකාවේ 'කළණ මිතුරන්' (Kalyana Mitra) ලෙස සමාජයට මග පෙන්වූ පිරිස කවුද?", "මහා සංඝරත්නය හා ගුරුවරුන්", "විදේශීය වෙළෙඳුන්", "හමුදා හේවායන්", "බදු එකතු කරන්නන්", "ගැමියන්ට ආගමික, සදාචාර හා අධ්‍යාපනික මගපෙන්වීම සංඝරත්නය මගින් ලැබිණි."),
    q(T, "පැරණි ලංකාවේ 'කැටයම් කලාව' හා 'ගෘහ නිර්මාණ ශිල්පය' හැදෑරීම සඳහා භාවිත කළ සාම්ප්‍රදායික ග්‍රන්ථය කුමක්ද?", "මඤ්ජුශ්‍රී භාෂිත වාස්තු විද්‍යා ශාස්ත්‍රය", "මහාවංශය", "දීපවංශය", "රාජාවලිය", "සංස්කෘත භාෂාවෙන් ලියැවුණු මෙම ග්‍රන්ථය ප්‍රතිමා, ස්තූප හා විහාර සැලසුම් විස්තර කරයි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ගඩොල්' නිෂ්පාදනයේදී මැටි පදම් කිරීමට යොදාගත් සම්ප්‍රදායික ද්‍රව්‍ය මොනවාද?", "හොඳින් පෙරාගත් මැටි, වැලි සහ දහයියා", "සිමෙන්ති සහ අළු", "තාර සහ තෙල්", "ප්ලාස්ටික් කුඩු", "දහයියා මිශ්‍ර මැටි පිළිස්සීමේදී සැහැල්ලු හා ශක්තිමත් ගඩොල් නිපදවීමට හැකි විය."),
    q(T, "පැරණි ලංකාවේ 'හුණු බදාම' (Lime Mortar) සැකසීම සඳහා යොදාගත් සාම්ප්‍රදායික මිශ්‍රණය කුමක්ද?", "හුණු, වැලි, උක් පැණි හා බෙලි යුෂ", "සිමෙන්ති සහ ජලය පමණක්", "තෙල් සායම්", "මැටි පමණක්", "ශාක යුෂ හා පැණි මිශ්‍ර කළ හුණු බදාමය ඉතා තදින් ගල් හා ගඩොල් එකිනෙක අලවා තැබීය."),
    q(T, "පැරණි ලංකාවේ 'ප්‍රදීපාගාර' හෝ සංඥා කුලුනු ලෙස භාවිත කළ බවට සාධක ඇති ස්ථාන මොනවාද?", "වෙරළබඩ කඳු ගැට හා වරාය පිවිසුම් (උදා — ගොඩවාය, මාන්තොට)", "මැද රට කඳුකරය පමණක්", "අනුරාධපුර නගර මධ්‍යය", "කලාවැව මැද", "නැව්වලට මග පෙන්වීමට වෙරළබඩ උස් ස්ථානවල ගිනි දල්වා සංඥා කෙරිණි."),
    q(T, "පැරණි ලංකාවේ මුදල් භාවිතය වර්ධනය වීමත් සමඟ 'පොලී ක්‍රමය' ක්‍රියාත්මක වූයේ කෙසේද?", "ධාන්‍ය හෝ මුදල් තැන්පත් කර වාර්ෂිකව නියමිත ප්‍රතිශතයකින් පොලිය ලබා ගැනීම", "පොලී අය කිරීම සම්පූර්ණයෙන් තහනම් වීම", "සියලු ධනය රාජසන්තක වීම", "විදේශීය මුදල් පමණක් ගෙවීම", "තෝණිගල සෙල්ලිපිය අනුව වී සඳහා 50%ක හා මුං සඳහා 25%ක වාර්ෂික පොලියක් ලැබිණි."),
    q(T, "පැරණි ලංකාවේ 'කළහුමණක' වෙළෙඳ සංගමය පිහිටා තිබුණේ කුමන ප්‍රදේශයේද?", "වවුනියාව තෝණිගල ආශ්‍රිත ප්‍රදේශයේ", "කොළඹ වරායේ", "ගාල්ල කොටුවේ", "යාපනය නගරයේ", "උතුරු මැද පළාතේ වෙළෙඳ සංගම් ග්‍රාමීය ආර්ථිකයේ මූල්‍ය කටයුතු මෙහෙයවීය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'සී සෑම' සඳහා යොදාගත් ප්‍රධාන උපකරණය කුමක්ද?", "නගුල (මී හරකුන් බඳින ලද ලී නගුල)", "ට්‍රැක්ටරය", "යකඩ උදැල්ල පමණක්", "දෑකැත්ත", "මී ගවයන් දෙදෙනෙකු බැඳි ලී නගුලෙන් වෙල් යාය සී සෑම සාම්ප්‍රදායික ක්‍රමය විය."),
    q(T, "වී ගොවිතැනේදී 'පෝරුව' භාවිත කළේ කුමන කාර්යය සඳහාද?", "සී සෑ කුඹුරේ පස සමතලා කර මඩ පදම් කිරීමට", "ගොයම් කැපීමට", "වී ඇට වැපිරීමට", "වී මැනීමට", "ලී පෝරුව මගින් කුඹුරේ ජලය ඒකාකාරව රඳන සේ මඩ බිම මට්ටම් කෙරිණි."),
    q(T, "ගොයම් පැසී කහ පැහැයට හැරුණු පසු අස්වැන්න නෙළීමට භාවිත කළ මෙවලම කුමක්ද?", "දෑකැත්ත", "නගුල", "කෙටේරිය", "පෝරුව", "දෑකැත්තෙන් ගොයම් කපා මිටි බැඳ කමතට ගෙන යාම සිදු විය."),
    q(T, "කමතේදී ගොයම් ගස්වලින් වී ඇට වෙන් කර ගැනීම සඳහා භාවිත කළ සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "මී හරකුන් ලවා ගොයම් පෑගවීම (කොළ මැඩවීම)", "විදුලි යන්ත්‍ර භාවිතය", "අතින් එකිනෙක කැඩීම", "ගින්නෙන් පිළිස්සීම", "බැඳි ගවයන් කමත වටා කරකවමින් ගොයම් ගස් පෑගවීමෙන් වී ඇට වෙන් කර ගැනිණි."),
    q(T, "පැරණි ලංකාවේ 'බොල්ල' හෙවත් 'කුල්ල' භාවිත කළේ කුමන කාර්යය සඳහාද?", "සුළඟ ආධාරයෙන් බොල් වී හා දහයියා ඉවත් කර පිරිසිදු වී වෙන් කර ගැනීමට", "බත් පිසීමට", "ජලය ඇදීමට", "පස හෑරීමට", "සුළඟට වී ඉහළ සිට දැමීමෙන් බරැති වී බිමට වැටෙන අතර බොල් වී සුළඟට ගසාගෙන යයි."),
    q(T, "පැරණි සමාජයේ 'බිත්තර වී' (Seed Paddy) තෝරා ගැනීමේදී දැක්වූ විශේෂ සැලකිල්ල කුමක්ද?", "පිරිසිදු, හොඳින් පැසුණු, කෘමි හානි නැති හොඳම ධාන්‍ය ඊළඟ කන්නය සඳහා සුරැකීම", "ඉවත දමන වී තෝරා ගැනීම", "වෙළෙඳපොළෙන් පමණක් මිලදී ගැනීම", "විදේශීය වී පමණක් සෙවීම", "ඊළඟ වගාව සාර්ථක කර ගැනීමට හොඳම බීජ ධාන්‍ය වෙන් කර අටුවල තැන්පත් කළහ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'වැවක ආරක්ෂාව' වෙනුවෙන් පනවා තිබූ දැඩි නීතියක් කුමක්ද?", "වැව් බැම්ම මත ගවයන් ගැටගැසීම හා බැම්මට හානි වන ක්‍රියා තහනම් කිරීම", "වැවේ මාළු බෑම අනිවාර්ය කිරීම", "වැවට කුණු දැමීම", "වැව සිඳී යාමට ඉඩ හැරීම", "වැව් බැම්ම කැඩී යාම මුළු ගමටම විනාශයක් ගෙන දෙන බැවින් එය ඉතා පරිස්සමින් රැක ගත්හ."),
    q(T, "පැරණි ලංකාවේ 'ප්‍රවේණි ඉඩම්' හිමි ගොවියෙකු මියගිය පසු එම ඉඩම හිමි වූයේ කා හටද?", "ඔහුගේ නීත්‍යානුකූල දරුවන්ට හෝ පවුලේ උරුමක්කාරයන්ට", "රජුට පමණක්", "විදේශීය වෙළෙන්දෙකුට", "ගමේ ප්‍රධානියාට", "පරවේණි ඉඩම් පරම්පරාවෙන් පරම්පරාවට අඛණ්ඩව භුක්ති විඳීමේ අයිතිය තිබුණි."),
    q(T, "පැරණි ලංකාවේ 'නින්දගම්' ක්‍රමය යනු කුමක්ද?", "රජු විසින් ප්‍රභූවරයෙකුට හෝ නිලධාරියෙකුට සේවය වෙනුවෙන් පවරා දුන් ගමක්", "විහාරස්ථානයකට පමණක් අයිති ගමක්", "ධීවර ගමක් පමණක්", "මුඩුබිම් ගමක්", "නින්දගම් ලාභියාට එම ගමේ වැසියන්ගෙන් සේවා හා ආදායම් ලබා ගැනීමට අයිතිය තිබුණි."),
    q(T, "පැරණි ලංකාවේ සමාජයේ 'ස්වයංපෝෂිත ග්‍රාමීය ආර්ථිකය' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "ගමට අවශ්‍ය ආහාර, ඇඳුම් හා මෙවලම් බොහෝ දුරට ගම තුළින්ම සපුරා ගැනීමට හැකි වීම", "මුදල් පමණක් භාවිත කිරීම", "සියලු භාණ්ඩ විදේශයන්ගෙන් ගෙන්වීම", "කිසිදු වෙළෙඳාමක් නොපැවතීම", "ලුණු හා ලෝහ වැනි සීමිත ද්‍රව්‍ය හැර අනෙක් සියල්ල ගමේම නිෂ්පාදනය කර ගැනිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ගංගා ආශ්‍රිත ප්‍රවාහනය' සඳහා වැඩි වශයෙන් යොදාගත් ප්‍රධාන ගංගා මොනවාද?", "මහවැලි ගඟ, කැලණි ගඟ, කළු ගඟ සහ වලවේ ගඟ", "කුඩා ඇළවල් පමණක්", "මුහුදු බොකු පමණක්", "වියළි ගංගා පමණක්", "පහළ නිම්න ප්‍රදේශවල පාරු මගින් දැව, මැණික් හා කුළුබඩු ප්‍රවාහනය කිරීමට ගංගා යොදා ගැනිණි."),
    q(T, "පැරණි සමාජයේ විහාරස්ථාන වෙත 'දානමාන' පිදීමේදී වඩාත් අගය කළ දානය කුමක්ද?", "සංඝික දානය (සිව්දිග මහා සංඝයා උදෙසා පිදීම)", "තනි පුද්ගලයෙකුට දෙන දානය", "රජුට දෙන තෑගි", "විදේශිකයන්ට දෙන දානය", "පුද්ගලික නොවී සංඝ සමාජයට පොදුවේ පූජා කිරීම මහත්ඵල මහානිසංස ගෙන දෙන බව විශ්වාස කෙරිණි."),
    q(T, "පැරණි ලංකාවේ 'ශිල්ප ශ්‍රේණි' සංවිධානය වී තිබීමෙන් නිෂ්පාදනවලට ලැබුණු ප්‍රධාන වාසිය කුමක්ද?", "නිෂ්පාදනවල ප්‍රමිතිය, ගුණාත්මකභාවය හා මිල ස්ථාවරව පවත්වා ගැනීමට හැකි වීම", "භාණ්ඩ සොරකම් කිරීමට හැකි වීම", "විදේශිකයන් රැවටීම", "කර්මාන්ත වැසී යාම", "ශ්‍රේණි මගින් ශිල්පීන්ට වෘත්තීය ආරක්ෂාව හා පුහුණුව ලබා දුනි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ රාජ්‍ය පාලන මූලධර්ම සහ නීති සංග්‍රහයන්හි 'යුක්තිය පසිඳලීමේදී' ප්‍රමුඛ වූයේ කුමක්ද?", "සාක්ෂි විභාග කර ධර්මානුකූලව හා අපක්ෂපාතීව තීන්දු දීම", "ධනවත් අයට පමණක් පක්ෂපාතී වීම", "පිටසක්වළ උපදෙස් ගැනීම", "කැමැත්ත අනුව තීන්දු වෙනස් කිරීම", "රජු සහ විනිසුරුවරුන් ධර්මයෙන් තොරව තීන්දු දීමෙන් රටට නියඟ හා විපත් එන බව විශ්වාස කෙරිණි."),
    q(T, "අනුරාධපුර යුගයේ රජුට සෘජුවම බදු ගෙවීම පැහැර හරින ලද අවස්ථාවක පනවන ලද සාමාන්‍ය ක්‍රියාමාර්ගය කුමක්ද?", "දේපළ තාවකාලිකව රජයට තහනම් කිරීම හෝ දඩ මුදලක් අය කිරීම", "සම්පූර්ණ පවුලම මරා දැමීම", "රටින් පිටුවහල් කිරීම පමණක්", "කිසිදු පියවරක් නොගැනීම", "බදු එකතු කිරීමේදී නීත්‍යානුකූල දඩ අය කිරීම බදුල්ල ලිපිය ආදී සෙල්ලිපිවල සඳහන් වේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ප්‍රාදේශීය නායකයන්' හා 'ගමිකවරුන්' අතර පැවති ධුරාවලිය කෙබඳු වීද?", "පරුමකවරුන් යටතේ ගමිකවරුන් ක්‍රියාත්මක වෙමින් ගම් මට්ටමේ පාලනය මෙහෙයවීම", "දෙදෙනා අතර කිසිදු සම්බන්ධයක් නොතිබීම", "ගමිකවරුන් රජුට වඩා බලවත් වීම", "විදේශිකයන් විසින් පාලනය කිරීම", "පරුමකවරුන් දිස්ත්‍රික් මට්ටමේ ප්‍රභූන් වූ අතර ගමිකවරුන් ග්‍රාමීය මට්ටමේ නායකයෝ වූහ."),
    q(T, "පැරණි ලංකාවේ 'වෙළෙඳ නැව්' ආරක්ෂිතව නවතා තැබීමට 'ස්වාභාවික වරායන්' තෝරා ගැනීමට හේතුව කුමක්ද?", "මෝසම් කුණාටු හා රළ පහරින් නැව් බිඳී යාම වැළැක්වීමට ස්වාභාවික ආවරණය ලැබීම", "ගොඩබිමට නැව් ඇද දැමීමට", "සතුරු ප්‍රහාරවලට ලක්වීමට", "කාර්මික කසළ බැහැර කිරීමට", "ත්‍රිකුණාමලය (ගෝකණ්ණ) ලොව විශිෂ්ටතම ස්වාභාවික වරායක් ලෙස පෙරදිග නාවිකයන් අතර ප්‍රකට විය."),
    q(T, "පැරණි ලංකාවේ 'පුවක්' සහ 'බුලත්' වෙළෙඳාම ආර්ථික වශයෙන් වැදගත් වූයේ ඇයි?", "දේශීය භාවිතයට අමතරව ඉන්දියාවට අපනයනය කළ ප්‍රධාන භාණ්ඩයක් වීම නිසා", "රෙදි සායම් කිරීමට පමණක්", "බෙහෙත් පෙති සෑදීමට", "නැව් තැනීමට", "ඉන්දියාව සමඟ පැවති වෙළෙඳාමේදී පුවක් සඳහා විශාල ඉල්ලුමක් පැවතුණි."),
    q(T, "පැරණි සමාජයේ විහාරස්ථාන සඳහා 'දාසයන්' පූජා කළ බවට සෙල්ලිපිවල සඳහන් වන විට එයින් අදහස් වූයේ කුමක්ද?", "විහාරස්ථානයේ පිරිසිදු කිරීම්, වතුපිටි නඩත්තුව හා තේවා කටයුතුවලට සේවකයන් පැවරීම", "භික්ෂූන්ට විකිණීමට", "හමුදා සෙබළුන් ලෙස යැවීමට", "විදේශිකයන්ට දීමට", "විහාරාරාම නඩත්තුවට සේවකයන් හා ඉඩම් පූජා කිරීම පුණ්‍ය කර්මයක් ලෙස සැලකිණි."),
    q(T, "පැරණි ලංකාවේ 'පෙහෙකරු' (Weavers) හෙවත් රෙදි වියන්නන්ගේ ප්‍රධාන මධ්‍යස්ථාන පිහිටා තිබුණේ කොහේද?", "අනුරාධපුරය ආශ්‍රිත නගරවල හා කපු වගා කළ රුහුණු ගම්මානවල", "කඳු මුදුන්වල", "මුහුදු නැව්වල", "ලෙන් තුළ පමණක්", "කපු වගාව ආශ්‍රිතව පෙහෙකරු ගම්මාන බිහි වූ බව මහාවංශයේ හා සෙල්ලිපිවල දැක්වේ."),
    q(T, "පැරණි සමාජයේ 'ලෝකුරුවන්' (Blacksmiths / Coppersmiths) විසින් නිපදවූ ප්‍රධාන යුද උපකරණ මොනවාද?", "කඩු, හෙල්ල, දුනු ඊතල තුඩු, කෙටේරි හා පලිහ", "තුවක්කු හා බෝම්බ", "ප්ලාස්ටික් ආවරණ", "කාලතුවක්කු පමණක්", "හමුදාවට අවශ්‍ය සියලුම ලෝහමය ආයුධ දේශීය කම්මල්කරුවන් අතින් නිමවිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ගඩොල් කැපීමේ' හා 'මැටි පිලිස්සීමේ' උදුන් හැඳින්වූයේ කුමන නමකින්ද?", "පෝරණු (Kilns)", "බිසෝකොටු", "අටු", "පැල්පත්", "ගඩොල්, උළු හා මැටි බඳුන් පිළිස්සීම සඳහා විශේෂ මැටි පෝරණු භාවිත කෙරිණි."),
    q(T, "පැරණි සිංහල සමාජයේ 'උළු සෙවිලි කළ ගෙවල්' තැනීමට අවසර හිමි වූයේ කා හටද?", "රජුට, ප්‍රභූන්ට සහ ආගමික විහාරස්ථානවලට පමණක්", "සියලු සාමාන්‍ය ජනයාට", "විදේශිකයන්ට පමණක්", "කිසිවෙකුට නොවේ", "සාමාන්‍ය ජනයා පිදුරු හෝ පොල් අතු සෙවිලි කළ නිවාසවල විසූ අතර උළු සෙවිලි කිරීම රාජකීය හා ආගමික වරප්‍රසාදයක් විය."),
    q(T, "පැරණි ලංකාවේ 'ගංගා මෝය' ආශ්‍රිතව පිහිටි ජනාවාසවල ජනයා කළ ප්‍රධාන අතිරේක ආර්ථික කටයුත්ත කුමක්ද?", "කරදිය හා මිරිදිය ධීවර කර්මාන්තය සහ ලුණු එකතු කිරීම", "හිම ක්‍රීඩා", "තේ වගාව", "මෝටර් රථ එකලස් කිරීම", "ගංගා මෝයවල ධීවර කටයුතු හා මුහුදු ගමන් ආශ්‍රිත ආර්ථික ක්‍රියාකාරකම් සිදුවිය."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'පවුල් සබඳතා' ශක්තිමත් කිරීමට හේතු වූ ප්‍රධාන සංස්කෘතික සාධකය කුමක්ද?", "වැඩිහිටියන්ට ගරු කිරීම, ඒකාබද්ධ පවුල් ක්‍රමය හා බෞද්ධ සාරධර්ම", "මුදල් තරඟකාරිත්වය", "නිරන්තර නඩු කීම", "තනිව විසීමේ ආශාව", "පවුලේ සියලු දෙනා එකමුතුව ගොවිතැන් හා සමාජ කටයුතුවල නිරත වීම පවුල් බැඳීම දැඩි කළේය."),
    q(T, "පැරණි ලංකාවේ 'දරුවන්ගේ අධ්‍යාපනය' ආරම්භ කිරීමේදී සිදු කළ සාම්ප්‍රදායික චාරිත්‍රය කුමක්ද?", "අත්පොත් තැබීම (හෝඩිය කියවීම)", "උසාවි යාම", "හමුදා පුහුණුව", "ගිවිසුම් ගැසීම", "සුබ නැකතින් පන්සලේ නායක හිමියන් හෝ ගුරුවරයා ලවා හෝඩිය කියවීමෙන් අධ්‍යාපනය ඇරඹිණි."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'පොදු පොකුණු' සහ 'නාන තටාක' නිර්මාණයේදී ජලය පිරිසිදු කර ගැනීමට යොදාගත් ක්‍රමය කුමක්ද?", "වැලි, අඟුරු හා ගල් බොරළු තට්ටු හරහා ජලය පෙරී ඒමට සැලැස්වීම", "ක්ලෝරීන් රසායන යෙදීම", "ජලය රත් කිරීම", "පාරජම්බුල කිරණ භාවිතය", "කුට්ටම් පොකුණ වැනි පොකුණුවලට ජලය ඇතුළු වන ස්ථානයේ පෙරහන් කුටි (Filtration chambers) තනා තිබුණි."),
    q(T, "පැරණි ලංකාවේ ආර්ථිකයේ 'ඇතුන් අල්ලා හීලෑ කිරීම' සිදු කළ විශේෂ ක්‍රමවේදය කුමක්ද?", "ඇත් ගාල (Kraal) බැඳ වන ඇතුන් කොටු කර හීලෑ ඇතුන් ආධාරයෙන් හීලෑ කිරීම", "වෙඩි තබා බිය ගැන්වීම", "උගුල් අටවා මරා දැමීම", "විදුලි සැර වැද්දවීම", "රාජකීය හමුදාවට හා විහාර කටයුතුවලට අවශ්‍ය ඇතුන් ඇත් ගාල් මගින් අල්ලා ගනු ලැබීය."),
    q(T, "පැරණි ශ්‍රී ලංකාවෙන් 'අපනයනය කළ ඇතුන්' විදේශයන්හි ඉහළින් අගය කිරීමට හේතුව කුමක්ද?", "ලාංකික ඇතුන් බුද්ධිමත්, යුද්ධයට දක්ෂ හා කීකරු සතුන් ලෙස ප්‍රකට වීම", "ඔවුන්ට පියාපත් තිබීම", "ඔවුන් කතා කිරීමට දැන සිටීම", "ඔවුන් කුඩා ප්‍රමාණයේ වීම", "ඉන්දියාව, පර්සියාව හා අරාබිය ලංකාවේ ඇතුන් ඉහළ මිලකට මිලදී ගත්හ."),
    q(T, "පැරණි රාජ්‍ය පාලන තන්ත්‍රයේදී රජු දිනපතා ජනතා දුක්ගැනවිලි ඇසීමට රැස් වූ සභාව හැඳින්වූයේ කුමන නමකින්ද?", "රාජ සභාව (මඟුල් මඩුව)", "පාර්ලිමේන්තුව", "කැබිනට් මණ්ඩලය", "සෙනෙට් සභාව", "රජු තම අමාත්‍යවරුන් හා නිලධාරීන් සමඟ සිහසුන මත හිඳිමින් යුක්තිය පසිඳලීය."),
    q(T, "පැරණි ලංකාවේ 'බ්‍රාහ්මණ' ප්‍රජාව සමාජයේ ඉටු කළ කාර්යභාරය කුමක්ද?", "නක්ෂත්‍ර කටයුතු, ශාන්තිකර්ම, රාජකීය හෝරා බැලීම හා රාජගුරු සේවය", "කම්මල් වැඩ කිරීම", "වැව් හෑරීම පමණක්", "යුද හමුදා සෙබළුන් පමණක් වීම", "බෞද්ධ සමාජයක් වුවද බ්‍රාහ්මණයන්ගේ වෛදික ශාස්ත්‍ර ඥානය රාජසභාවල පිළිගැනුණි."),
    q(T, "පැරණි ලංකාවේ 'සෙල්ලිපි කෙටීමේ ශිල්පීන්' සෙල්ලිපිවල තමන් හඳුන්වා ගත්තේ කුමන නමකින්ද?", "රුපදක (ශිලා කැටයම් ශිල්පියා)", "ලේකම්", "සෙනෙවි", "ගමික", "ගල් මත අක්ෂර හා කැටයම් කෙටූ දක්ෂ ශිල්පීහු ඇතැම් ලිපිවල තම නම සටහන් කළහ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'කෘෂිකාර්මික ශිෂ්ටාචාරයේ' පැවැත්මට ජල සම්පත කළමනාකරණය කිරීම අත්‍යවශ්‍ය සාධකයක් වූයේ ඇයි?", "ඊසානදිග මෝසම් වර්ෂාව වසරේ මාස 3-4කට පමණක් සීමා වී ඉතිරි මාස වියළිව පැවතීම නිසා", "සෑම දිනකම වැසි වැටීම නිසා", "ජලය නොමැතිව වී වැවිය හැකි නිසා", "මුහුදු ජලය ගොවිතැනට යොදාගත් නිසා", "වර්ෂා කාලයේ ජලය මහා වැව්වල ගබඩා කර නොගත්තේ නම් වියළි කලාපයේ ජනාවාස පවත්වා ගත නොහැකි විය."),
    q(T, "පැරණි සිංහල සමාජයේ 'ගම්මුලාදෑනි' හෙවත් ග්‍රාම නායකයා සතු වූ සදාචාරාත්මක ගුණාංගය කුමක්ද?", "ගැමියන් කෙරෙහි පියෙකු මෙන් සාධාරණව හා කාරුණිකව කටයුතු කිරීම", "ගැමියන්ගේ දේපළ පැහැර ගැනීම", "රජුට විරුද්ධව කැරලි ගැසීම", "විදේශිකයන්ට රට පාවා දීම", "ග්‍රාම නායකයාගේ නායකත්වය මත ගමේ සාමය හා කෘෂිකාර්මික කටයුතු සාර්ථකව මෙහෙයවිණි."),
    q(T, "පැරණි ලංකාවේ ආර්ථිකයේ 'පොල්' වගාව සම්බන්ධයෙන් අනුරාධපුර යුගයේදී දැකිය හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "ගෘහස්ථ පරිභෝජනය හා තෙල් ලබා ගැනීම සඳහා ගෙවතු වගාවක් ලෙස පැවතීම", "විශාල වාණිජ වතු ලෙස වගා කිරීම", "පොල් කිසිසේත්ම නොතිබීම", "අපනයන බෝගයක් පමණක් වීම", "පසුකාලීනව වාණිජ බෝගයක් වූ පොල් මුල් යුගයේ ගෙවතු බෝගයක් ලෙස පැවතුණි."),
    q(T, "අනුරාධපුර යුගයේ 'අග්බෝ රජවරුන්' විසින් කරවන ලද අක්කර දහස් ගණනක කෘෂිකර්මාන්තයට දායක වූ විශාලතම වැවක් වන්නේ කුමක්ද?", "කන්තලේ වැව (ගංගාතලාව)", "පරාක්‍රම සමුද්‍රය", "බොරලැස්ගමුව වැව", "බේරේ වැව", "දෙවන අග්බෝ රජු විසින් කන්තලේ වැව සහ ගිරිතලේ වැව කරවන ලදී."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ ජනාවාස ව්‍යාප්තියේදී ගංගා මිටියාවත් ප්‍රමුඛ වීමට බලපෑ භූගෝලීය හේතුව කුමක්ද?", "ගංවතුරෙන් තැන්පත් වන සාරවත් අළුහිරු පස හා නිරන්තර මිරිදිය ජල සැපයුම", "ගංගාවල රත්‍රන් පාවී ඒම", "මුහුදු නැව් ගොඩබිමට ඒම", "කඳුකර ප්‍රදේශ ජනාවාස කිරීමට නොහැකි වීම", "මල්වතු ඔය, දැදුරු ඔය, කලා ඔය ආදී නිම්නවල පස ඉතා සාරවත් විය."),
    q(T, "පැරණි සිංහල ජනාවාස හා රාජ්‍ය පාලන සම්ප්‍රදායේ ප්‍රධාන හරය වූයේ කුමක්ද?", "ධාර්මික රාජ්‍ය පාලනය සහ ස්වයංපෝෂිත කෘෂිකාර්මික පරිසර පද්ධතිය", "යුද ආක්‍රමණ පමණක් කිරීම", "විදේශ රටවල් කොල්ලකෑම", "ස්වභාවධර්මය සම්පූර්ණයෙන් විනාශ කිරීම", "මිනිසා හා පරිසරය අතර මනා සමතුලිතතාවක් පවත්වා ගනිමින් බෞද්ධ සාරධර්ම මත පදනම් වූ ශිෂ්ටාචාරයක් ගොඩනැගුණි.")
  )
}



